        [v5_button("💾 بکاپ", "V5|A|B"), v5_button("📜 گزارش‌ها", "V5|A|L")],
        [v5_button("⚡ ویرایشگر همه‌چیز", "V5|A|Z"), v5_button("🧰 ابزارها", "V5|A|X")],
