        await safe_edit_query(query,v5_card("⚠️ پایان همه بازی‌ها","تمام Lobbyها و بازی‌های فعال بسته می‌شوند."),ar6_confirm_markup(f"V7|A|PEY|{token}","V7|A|P")); return
