def v16_user_card(uid: int) -> str:
    u = get_user(uid)
    gender = user_gender(uid)
    g_label = GENDER_LABELS.get(gender, "👤 نامشخص")
    g_icon = user_gender_icon(uid)
    username = u.get("username") or "-"
    return (
        f"👤 <b>{escape(u.get('name', 'کاربر'))}</b> {g_icon}\n"
        "______________________\n"
        f"🆔 ID: <code>{uid}</code>\n"
        f"🔗 یوزرنیم: {escape('@' + str(username)) if username != '-' else '-'}\n"
        f"🚻 جنسیت: <b>{g_label}</b>\n"
        f"🔞 تأیید ۱۸+: <b>{'✅ دارد' if u.get('adult_ok') else '❌ ندارد'}</b>\n"
        f"⭐ سطح: <b>{int(u.get('level', 1))}</b> · XP: <b>{int(u.get('xp', 0))}</b> · 💰 سکه: <b>{int(u.get('coins', 0))}</b>\n"
        f"🎮 بازی‌ها: <b>{int(u.get('games', 0))}</b> · 🏆 برد: <b>{int(u.get('wins', 0))}</b>\n"
        f"{'🚫 <b>مسدود شده</b>' if u.get('banned') else '🟢 فعال'}"
    )


def v16_users_page(offset: int):
    uids = sorted(DATA.get("users", {}).keys(), key=lambda x: int(x))
    total = len(uids)
    page = uids[offset:offset + A16_PAGE]
    rows = []
    for uid in page:
        u = DATA["users"][uid]
        g_icon = user_gender(int(uid))
        ban_mark = " 🚫" if u.get("banned") else ""
        rows.append([v5_button(f"{user_gender_icon(int(uid))} {str(u.get('name', 'کاربر'))[:18]}{ban_mark}", f"A16|U|VIEW|{uid}")])  # [FIX] button labels are plain text — escape+slice corrupted them
    nav = []
    if offset > 0:
        nav.append(v5_button("◀️ قبلی", f"A16|U|PG|{max(0, offset - A16_PAGE)}"))
    nav.append(v5_button(f"📄 {total} کاربر", "A16|NONE"))
    if offset + A16_PAGE < total:
        nav.append(v5_button("بعدی ▶️", f"A16|U|PG|{offset + A16_PAGE}"))
    rows.append(nav)
    rows.append([v5_button("🔍 جست‌وجو", "A16|U|SEARCH"), v5_button("⌂ خانه", "A16|HOME")])
    body = (
        "👥 <b>مدیریت کاربران</b>\n"
        "______________________\n"
        f"مجموع: <b>{total}</b> · مسدود: <b>{sum(1 for u in DATA['users'].values() if u.get('banned'))}</b>\n"
        f"👦 پسر: <b>{sum(1 for u in DATA['users'].values() if u.get('gender') == 'male')}</b> · "
        f"👧 دختر: <b>{sum(1 for u in DATA['users'].values() if u.get('gender') == 'female')}</b> · "
        f"👤 نامشخص: <b>{sum(1 for u in DATA['users'].values() if not u.get('gender'))}</b>\n\n"
        "یکی را انتخاب کن 👇"
    )
    return body, v5_markup(rows)


async def v16_broadcast_run(query, text: str):
    bot = APEX_RUNTIME_BOT or getattr(query.message, "get_bot", lambda: None)()
    targets = [int(k) for k in DATA.get("users", {}).keys()]
    total = len(targets)
    ok = fail = 0
    sent = 0
    status = None
    header = "📣 <b>ارسال همگانی ApexRival</b>\n______________________\n"
    try:
        status = await query.message.reply_text(header + f"⏳ در حال ارسال… 0/{total}")
    except Exception:
        status = None
    for i, uid in enumerate(targets, 1):
        try:
            await bot.send_message(chat_id=uid, text=f"📣 <b>ApexRival</b>\n\n{escape(text[:3500])}", parse_mode=ParseMode.HTML)
            ok += 1
        except Exception:
            fail += 1
        sent = i
        if status is not None and (i % 20 == 0 or i == total):
            try:
                await status.edit_text(
                    header + f"📡 پیشرفت: <b>{sent}/{total}</b>\n✅ موفق: <b>{ok}</b> · ❌ ناموفق: <b>{fail}</b>",
                    parse_mode=ParseMode.HTML,
                )
            except Exception:
                pass
    if status is not None:
        try:
            await status.edit_text(
                header + f"🎉 <b>تمام شد!</b>\n\n✅ موفق: <b>{ok}</b>\n❌ ناموفق: <b>{fail}</b>\n👥 کل مخاطبان: <b>{total}</b>",
                parse_mode=ParseMode.HTML,
            )
        except Exception:
            pass
    DATA.setdefault("broadcast_log", []).append({"ts": now_ts(), "actor": int(query.from_user.id), "ok": ok, "fail": fail, "total": total})
    DATA["broadcast_log"] = DATA["broadcast_log"][-100:]
    save_data(force=True)
    audit("v16_broadcast", int(query.from_user.id), None, f"ok={ok},fail={fail}")
    return ok, fail


def v16_admin_home_text() -> str:
    users = DATA.get("users", {})
    day_ago = now_ts() - 86400
    new_24 = sum(1 for u in users.values() if int(u.get("joined_at", 0) or 0) >= day_ago)
    started = DATA.get("started_users", {})
    active_games = [g for g in DATA.get("games", {}).values() if g.get("status") in ("active", "lobby")]
    lobbies = sum(1 for g in active_games if g.get("status") == "lobby")
    prompts_total = sum(len(v) for v in V7_BANKS_FINAL.values())
    adult_ok = sum(1 for u in users.values() if u.get("adult_ok"))
    return (
        "👑 <b>ApexRival — مرکز مدیریت v16</b>\n"
        "______________________\n"
        f"👥 کاربران: <b>{len(users)}</b> · 🆕 جدید ۲۴س: <b>{new_24}</b> · 🔑 فعال‌شده: <b>{len(started)}</b>\n"
        f"🚻 👦 <b>{sum(1 for u in users.values() if u.get('gender') == 'male')}</b> · "
        f"👧 <b>{sum(1 for u in users.values() if u.get('gender') == 'female')}</b> · "
        f"🔞 ۱۸+ تأییدشده: <b>{adult_ok}</b>\n"
        f"🌐 گروه‌ها: <b>{len(DATA.get('groups', {}))}</b> · 🎮 بازی‌های زنده: <b>{len(active_games)}</b> (لابی: {lobbies})\n"
        f"📚 سؤال‌ها/جرئت‌ها: <b>{prompts_total}</b> در <b>{len(V7_BANKS_FINAL)}</b> بانک\n"
        f"🚫 مسدود: <b>{sum(1 for u in users.values() if u.get('banned'))}</b> · "
        f"🔒 گیت گروه: <b>{'سخت‌گیرانه' if ar16_gate_mode() == 'on' else 'باز (پیش‌فرض)'}</b>\n"
        "______________________\n"
        "🛠 هر بخش را از دکمه‌های زیر انتخاب کن 👇"
    )


