async def v16_admin_router(update, context):
    query = getattr(update, "callback_query", None)
    if not query or not query.data:
        return
    data = str(query.data)
    if not data.startswith("A16|"):
        return
    uid = int(query.from_user.id)
    if not is_admin(uid):
        await safe_answer_query(query, "🚫 فقط Super Admin.", True)
        return
    await safe_answer_query(query)
    parts = data.split("|")
    section = parts[1] if len(parts) > 1 else "HOME"
    sub = parts[2] if len(parts) > 2 else "HOME"
    arg = parts[3] if len(parts) > 3 else ""
    try:
        if section == "HOME":
            await v16_admin_home_render(query)
            return
        if section == "NONE":
            return
        # ---------------- USERS ----------------
        if section == "U":
            if sub == "PG":
                offset = int(arg or 0)
                body, markup = v16_users_page(offset)
                await safe_edit_query(query, body, markup)
                return
            if sub == "VIEW":
                target = int(arg)
                if target not in {int(k) for k in DATA.get("users", {})}:
                    await safe_answer_query(query, "❌ کاربر پیدا نشد.", True)
                    return
                u = get_user(target)
                rows = [
                    [v5_button("🔨 بن / رفع بن", f"A16|U|BAN|{target}"),
                     v5_button("🔞 تغییر ۱۸+", f"A16|U|18|{target}")],
                    [v5_button("👦 تعیین پسر", f"A16|U|GEN|{target}|M"),
                     v5_button("👧 تعیین دختر", f"A16|U|GEN|{target}|F")],
                    [v5_button("➕ XP", f"A16|U|XP|{target}"),
                     v5_button("💰 سکه", f"A16|U|COIN|{target}")],
                    [v5_button("🗑 حذف حساب", f"A16|U|DEL|{target}")],
                    [v5_button("👥 فهرست", "A16|U|PG|0"), v5_button("⌂ خانه", "A16|HOME")],
                ]
                await safe_edit_query(query, v16_user_card(target), v5_markup(rows))
                return
            if sub == "BAN":
                target = int(arg)
                u = get_user(target)
                u["banned"] = not bool(u.get("banned", False))
                save_data(force=True)
                audit("v16_ban_toggle", uid, None, f"{target}:{u['banned']}")
                await safe_answer_query(query, "🚫 مسدود شد." if u["banned"] else "✅ رفع مسدودی شد.")
                await safe_edit_query(query, v16_user_card(target), v5_markup([
                    [v5_button("🔨 بن / رفع بن", f"A16|U|BAN|{target}"), v5_button("🔞 تغییر ۱۸+", f"A16|U|18|{target}")],
                    [v5_button("👦 تعیین پسر", f"A16|U|GEN|{target}|M"), v5_button("👧 تعیین دختر", f"A16|U|GEN|{target}|F")],
                    [v5_button("➕ XP", f"A16|U|XP|{target}"), v5_button("💰 سکه", f"A16|U|COIN|{target}")],
                    [v5_button("🗑 حذف حساب", f"A16|U|DEL|{target}")],
                    [v5_button("👥 فهرست", "A16|U|PG|0"), v5_button("⌂ خانه", "A16|HOME")],
                ]))
                return
            if sub == "18":
                target = int(arg)
                u = get_user(target)
                u["adult_ok"] = not bool(u.get("adult_ok", False))
                save_data(force=True)
                audit("v16_adult_toggle", uid, None, f"{target}:{u['adult_ok']}")
                await safe_answer_query(query, "🔞 ۱۸+ فعال شد." if u["adult_ok"] else "🔞 ۱۸+ خاموش شد.")
                await safe_edit_query(query, v16_user_card(target), v5_markup([
                    [v5_button("🔨 بن / رفع بن", f"A16|U|BAN|{target}"), v5_button("🔞 تغییر ۱۸+", f"A16|U|18|{target}")],
                    [v5_button("👦 تعیین پسر", f"A16|U|GEN|{target}|M"), v5_button("👧 تعیین دختر", f"A16|U|GEN|{target}|F")],
                    [v5_button("➕ XP", f"A16|U|XP|{target}"), v5_button("💰 سکه", f"A16|U|COIN|{target}")],
                    [v5_button("🗑 حذف حساب", f"A16|U|DEL|{target}")],
                    [v5_button("👥 فهرست", "A16|U|PG|0"), v5_button("⌂ خانه", "A16|HOME")],
                ]))
                return
            if sub == "GEN":
                target = int(arg)
                choice = "male" if (len(parts) > 4 and parts[4] == "M") else "female"
                get_user(target)["gender"] = choice
                save_data(force=True)
                audit("v16_gender_set", uid, None, f"{target}:{choice}")
                await safe_answer_query(query, "✅ جنسیت ثبت شد.")
                await safe_edit_query(query, v16_user_card(target), v5_markup([
                    [v5_button("🔨 بن / رفع بن", f"A16|U|BAN|{target}"), v5_button("🔞 تغییر ۱۸+", f"A16|U|18|{target}")],
                    [v5_button("👦 تعیین پسر", f"A16|U|GEN|{target}|M"), v5_button("👧 تعیین دختر", f"A16|U|GEN|{target}|F")],
                    [v5_button("➕ XP", f"A16|U|XP|{target}"), v5_button("💰 سکه", f"A16|U|COIN|{target}")],
                    [v5_button("🗑 حذف حساب", f"A16|U|DEL|{target}")],
                    [v5_button("👥 فهرست", "A16|U|PG|0"), v5_button("⌂ خانه", "A16|HOME")],
                ]))
                return
            if sub in ("XP", "COIN"):
                target = int(arg)
                A16_FLOW[uid] = {"type": "user_adjust", "uid": target, "what": "xp" if sub == "XP" else "coins"}
                await safe_edit_query(query, v16_user_card(target) + "\n\n➕ عدد را بفرست:", v5_markup([[v5_button("❌ لغو", "A16|U|VIEW|" + str(target))]]))
                return
            if sub == "DEL":
                target = int(arg)
                await safe_edit_query(query, v16_user_card(target) + "\n\n⚠️ <b>حذف حساب برای همیشه؟</b>", v5_markup([
                    [v5_button("🗑 بله، حذف کن", f"A16|U|DELOK|{target}")],
                    [v5_button("🔙 انصراف", f"A16|U|VIEW|{target}")],
                ]))
                return
            if sub == "DELOK":
                target = int(arg)
                DATA.get("users", {}).pop(str(target), None)
                for g in DATA.get("games", {}).values():
                    g["players"] = [p for p in g.get("players", []) if int(p) != target]
                save_data(force=True)
                audit("v16_user_delete", uid, None, str(target))
                body, markup = v16_users_page(0)
                await safe_edit_query(query, "🗑 حساب حذف شد.\n\n" + body, markup)
                return
            if sub == "SEARCH":
                A16_FLOW[uid] = {"type": "user_search"}
                await safe_edit_query(query, "🔍 <b>جست‌وجوی کاربر</b>\n\nID عددی یا بخشی از اسم را بفرست:", v5_markup([[v5_button("❌ لغو", "A16|U|PG|0")]]))
                return
        # ---------------- BROADCAST ----------------
        if section == "B":
            if sub == "HOME":
                A16_FLOW[uid] = {"type": "broadcast_text"}
                await safe_edit_query(
                    query,
                    "📣 <b>ارسال همگانی</b>\n"
                    "______________________\n"
                    f"👥 مخاطبان: <b>{len(DATA.get('users', {}))}</b> کاربر\n\n"
                    "پیام را همین‌جا بفرست تا برای همه ارسال شود (HTML پشتیبانی می‌شود):",
                    v5_markup([[v5_button("❌ لغو", "A16|HOME")]]),
                )
                return
            if sub == "GO":
                flow = A16_FLOW.pop(uid, None) or {}
                text = str(flow.get("text") or "").strip()
                if not text:
                    await safe_answer_query(query, "❌ متنی ثبت نشده بود.", True)
                    await v16_admin_home_render(query)
                    return
                await safe_edit_query(query, "📡 ارسال آغاز شد…")
                await v16_broadcast_run(query, text)
                return
        # ---------------- CONTENT ----------------
        if section == "C":
            if sub == "HOME":
                rows = []
                pair = []
                for key in V16_BANK_KEYS_ORDER:
                    count = len(V7_BANKS_FINAL.get(key, []))
                    label = V7_MODE_LABELS.get(key, {"penalty": "☠️ حکم‌ها", "adult_male": "🔞 ۱۸+ پسرانه", "adult_female": "🔞 ۱۸+ دخترانه"}.get(key, key))
                    pair.append(v5_button(f"{label} ({count})", f"A16|C|BANK|{key}|0"))
                    if len(pair) == 2:
                        rows.append(pair)
                        pair = []
                if pair:
                    rows.append(pair)
                rows.append([v5_button("⌂ خانه", "A16|HOME")])
                await safe_edit_query(
                    query,
                    "📝 <b>مدیریت محتوا</b>\n"
                    "______________________\n"
                    f"📚 مجموع: <b>{sum(len(v) for v in V7_BANKS_FINAL.values())}</b> سؤال/جرئت در <b>{len(V16_BANK_KEYS_ORDER)}</b> بانک\n\n"
                    "بانک موردنظر را انتخاب کن تا ببینی، اضافه کنی یا حذف کنی:",
                    v5_markup(rows),
                )
                return
            if sub == "BANK":
                key = arg
                offset = int(parts[4] if len(parts) > 4 else 0) or 0
                bank = V7_BANKS_FINAL.get(key, [])
                custom = set(DATA.get("v16_custom_prompts", {}).get(key, []))
                page = bank[offset:offset + 5]
                rows = []
                for item in page:
                    mark = "✏️" if item in custom else "🔒"
                    idx = bank.index(item)
                    rows.append([v5_button(f"{mark} {escape(item)[:28]}", f"A16|C|DEL|{key}|{idx}")])
                nav = []
                if offset > 0:
                    nav.append(v5_button("◀️ قبلی", f"A16|C|BANK|{key}|{max(0, offset - 5)}"))
                if offset + 5 < len(bank):
                    nav.append(v5_button("بعدی ▶️", f"A16|C|BANK|{key}|{offset + 5}"))
                if nav:
                    rows.append(nav)
                rows.append([v5_button("➕ افزودن سؤال", f"A16|C|ADD|{key}")])
                rows.append([v5_button("🔙 بانک‌ها", "A16|C|HOME"), v5_button("⌂ خانه", "A16|HOME")])
                label = V7_MODE_LABELS.get(key, key)
                await safe_edit_query(
                    query,
                    f"📝 <b>{escape(label)}</b>\n"
                    "______________________\n"
                    f"تعداد: <b>{len(bank)}</b> · ✏️ سفارشی: <b>{len(custom)}</b>\n"
                    f"نمایش: <b>{offset + 1}–{min(offset + 5, len(bank))}</b>\n\n"
                    "🔒 = اصلی · ✏️ = اضافه‌شده از پنل (با لمس حذف می‌شود):",
                    v5_markup(rows),
                )
                return
            if sub == "ADD":
                key = arg
                A16_FLOW[uid] = {"type": "content_add", "key": key}
                label = V7_MODE_LABELS.get(key, key)
                await safe_edit_query(
                    query,
                    f"➕ <b>افزودن به بانک «{escape(label)}»</b>\n\nمتن سؤال/جرئت را بفرست:",
                    v5_markup([[v5_button("❌ لغو", f"A16|C|BANK|{key}|0")]]),
                )
                return
            if sub == "DEL":
                key = arg
                idx = int(parts[4] if len(parts) > 4 else 0)
                bank = V7_BANKS_FINAL.get(key, [])
                if 0 <= idx < len(bank):
                    text = bank[idx]
                    ok = v16_del_prompt(key, text)
                    audit("v16_prompt_delete", uid, None, f"{key}:{idx}")
                    await safe_answer_query(query, "🗑 حذف شد." if ok else "⚠️ حذف نشد.", not ok)
                await v16_admin_router_refresh_bank(query, key)
                return
        # ---------------- GAMES ----------------
        if section == "G":
            if sub == "HOME":
                games = [g for g in DATA.get("games", {}).values() if g.get("status") in ("active", "lobby")]
                if not games:
                    await safe_edit_query(query, v5_card("🎮 بازی‌های زنده", "فعلاً بازی فعالی وجود ندارد."), v5_markup([[v5_button("⌂ خانه", "A16|HOME")]]))
                    return
                rows = []
                for g in games[:8]:
                    status_icon = "🟢" if g.get("status") == "active" else "🎟"
                    rows.append([v5_button(f"{status_icon} {escape(str(g.get('id', '')))[:20]} · {len(g.get('players', []))} 👤", f"A16|G|VIEW|{str(g.get('id'))}")])  # [FIX] [:24] truncated the gid so the exact-match lookup never found the game
                rows.append([v5_button("🔄 بروزرسانی", "A16|G|HOME"), v5_button("⌂ خانه", "A16|HOME")])
                await safe_edit_query(
                    query,
                    "🎮 <b>بازی‌های زنده</b>\n______________________\n"
                    f"مجموع: <b>{len(games)}</b> (لابی: <b>{sum(1 for g in games if g.get('status') == 'lobby')}</b>)\n\nانتخاب کن:",
                    v5_markup(rows),
                )
                return
            if sub == "VIEW":
                game = DATA.get("games", {}).get(arg)
                if not game:
                    await safe_answer_query(query, "⛔ بازی پیدا نشد.", True)
                    return
                players = [int(p) for p in game.get("players", [])]
                lines = [f"{user_gender_icon(p)} {escape(name_of(p, game))}" for p in players[:10]]
                scores = game.get("round_scores", {})
                await safe_edit_query(
                    query,
                    "🎮 <b>جزئیات بازی</b>\n"
                    "______________________\n"
                    f"🆔 ID: <code>{escape(str(game.get('id', ''))[:30])}</code>\n"
                    f"🌐 گروه: <code>{game.get('chat_id')}</code>\n"
                    f"وضعیت: <b>{escape(game.get('status', '-'))}</b> · فاز: <b>{escape(str(game.get('phase', '-')))}</b>\n"
                    f"🔢 دور: <b>{game.get('round', 0)}</b> · نوبت: <b>{game.get('turn_number', 0)}</b>\n"
                    f"👥 بازیکنان (<b>{len(players)}</b>):\n" + ("\n".join(lines) if lines else "-") +
                    (f"\n\n🎤 پرسشگر فعلی: {escape(name_of(int(game.get('current_questioner') or 0), game))}" if game.get('current_questioner') else ""),
                    v5_markup([
                        [v5_button("🛑 پایان اجباری بازی", f"A16|G|END|{str(game.get('id'))}")],  # [FIX] same [:24] truncation bug
                        [v5_button("🎮 فهرست", "A16|G|HOME"), v5_button("⌂ خانه", "A16|HOME")],
                    ]),
                )
                return
            if sub == "END":
                game = DATA.get("games", {}).get(arg)
                if game:
                    end_game(game, "پایان اجباری از پنل مدیریت")
                    save_data(force=True)
                    audit("v16_force_end", uid, int(game.get("chat_id", 0)), str(game.get("id")))
                    await safe_answer_query(query, "🛑 بازی پایان یافت.")
                await v16_admin_home_render(query)
                return
        # ---------------- GROUPS ----------------
        if section == "R":
            if sub == "PG":
                offset = int(arg or 0)
                cids = sorted(DATA.get("groups", {}).keys(), key=lambda x: int(x))
                total = len(cids)
                page = cids[offset:offset + A16_PAGE]
                rows = []
                for cid in page:
                    rows.append([v5_button(f"🌐 {cid}", f"A16|R|VIEW|{cid}")])
                nav = []
                if offset > 0:
                    nav.append(v5_button("◀️ قبلی", f"A16|R|PG|{max(0, offset - A16_PAGE)}"))
                if offset + A16_PAGE < total:
                    nav.append(v5_button("بعدی ▶️", f"A16|R|PG|{offset + A16_PAGE}"))
                if nav:
                    rows.append(nav)
                rows.append([v5_button("⌂ خانه", "A16|HOME")])
                await safe_edit_query(
                    query,
                    f"🌐 <b>گروه‌ها</b>\n______________________\nمجموع: <b>{total}</b>\n\nانتخاب کن:",
                    v5_markup(rows),
                )
                return
            if sub == "VIEW":
                await v16_group_view_render(query, int(arg))
                return
            if sub in ("EN", "AD"):
                cid = int(arg)
                g = get_group(cid)
                if sub == "EN":
                    g["enabled"] = not bool(g.get("enabled", True))
                else:
                    g["adult_mode"] = not bool(g.get("adult_mode", False))
                save_data(force=True)
                audit(f"v16_group_{sub.lower()}", uid, cid, str(g.get("enabled" if sub == "EN" else "adult_mode")))
                await safe_answer_query(query, "✅ ذخیره شد.")
                await v16_group_view_render(query, cid)
                return
        # ---------------- SETTINGS ----------------
        if section == "S":
            if sub == "HOME":
                await v16_settings_render(query)
                return
            if sub == "GATE":
                new_mode = "on" if ar16_gate_mode() != "on" else "off"
                DATA["settings"]["group_gate_mode"] = new_mode
                save_data(force=True)
                audit("v16_gate_mode", uid, None, new_mode)
                await safe_answer_query(query, f"🔒 گیت گروه: {'سخت‌گیرانه' if new_mode == 'on' else 'باز (پیش‌فرض)'}")
                await v16_settings_render(query)
                return
            if sub == "MNT":
                settings = DATA.setdefault("settings", {})
                settings["maintenance"] = not bool(settings.get("maintenance", False))
                save_data(force=True)
                audit("v16_maintenance", uid, None, str(settings["maintenance"]))
                await safe_answer_query(query, "🛠 ذخیره شد.")
                await v16_settings_render(query)
                return
            if sub == "CHAN":
                A16_FLOW[uid] = {"type": "channel_edit", "field": "channel"}
                await safe_edit_query(query, f"📢 کانال فعلی: <code>{escape(REQUIRED_CHANNEL)}</code>\n\nکانال جدید را بفرست (مثل @Channel):", v5_markup([[v5_button("❌ لغو", "A16|S|HOME")]]))
                return
            if sub == "URL":
                A16_FLOW[uid] = {"type": "channel_edit", "field": "url"}
                await safe_edit_query(query, f"🔗 لینک فعلی: <code>{escape(REQUIRED_CHANNEL_URL)}</code>\n\nلینک جدید را بفرست:", v5_markup([[v5_button("❌ لغو", "A16|S|HOME")]]))
                return
            if sub in ("MIN", "MAX"):
                A16_FLOW[uid] = {"type": "setting_default", "field": "min_players_default" if sub == "MIN" else "max_players_default"}
                await safe_edit_query(query, "👥 عدد جدید را بفرست:", v5_markup([[v5_button("❌ لغو", "A16|S|HOME")]]))
                return
        # ---------------- LOGS ----------------
        if section == "L":
            entries = list(DATA.get("audit", []))[-15:]
            lines = [f"• <code>{escape(str(e.get('ts', ''))[-8:])}</code> {escape(str(e.get('action', '')))} — {escape(str(e.get('actor', '')))}" for e in reversed(entries)]
            await safe_edit_query(
                query,
                "📋 <b>لاگ عملیات (آخرین ۱۵)</b>\n______________________\n" + ("\n".join(lines) if lines else "خالی است."),
                v5_markup([[v5_button("🔄 بروزرسانی", "A16|L|HOME"), v5_button("⌂ خانه", "A16|HOME")]]),
            )
            return
        # ---------------- HEALTH ----------------
        if section == "H":
            try:
                size = Path(DATA_FILE).stat().st_size if Path(DATA_FILE).exists() else 0
            except Exception:
                size = 0
            await safe_edit_query(
                query,
                "🩺 <b>سلامت ربات</b>\n"
                "______________________\n"
                f"🤖 نسخه: <b>ApexRival {AR16_VERSION}</b>\n"
                f"💾 حجم داده: <b>{ar9_num(size)}</b> بایت\n"
                f"📚 بانک‌ها: <b>{len(V7_BANKS_FINAL)}</b> · مجموع سؤال‌ها: <b>{sum(len(v) for v in V7_BANKS_FINAL.values())}</b>\n"
                f"🎮 بازی‌ها (کل): <b>{len(DATA.get('games', {}))}</b>\n"
                f"🔑 Super Admin: <b>{'OK' if ADMIN_ID else 'MISSING'}</b>\n"
                f"⚙️ گیت گروه: <b>{ar16_gate_mode()}</b> · 🛠 بروزرسانی: <b>{'روشن' if v16_maintenance() else 'خاموش'}</b>\n"
                f"⏰ سرویس از: <code>{time.strftime('%H:%M:%S', time.localtime(AR16_BOOT_TS))}</code>",
                v5_markup([[v5_button("🔄 بروزرسانی", "A16|H|HOME"), v5_button("⌂ خانه", "A16|HOME")]]),
            )
            return
    except Exception as exc:
        audit("v16_admin_router_error", uid, None, repr(exc)[:300])
        try:
            await safe_answer_query(query, "⚠️ عملیات انجام نشد.", True)
        except Exception:
            pass


async def v16_admin_router_refresh_bank(query, key):
    class _FakeUpdate:
        pass
    # ساده: مستقیم صفحه‌ی بانک را دوباره رندر می‌کنیم
    bank = V7_BANKS_FINAL.get(key, [])
    custom = set(DATA.get("v16_custom_prompts", {}).get(key, []))
    page = bank[0:5]
    rows = []
    for item in page:
        mark = "✏️" if item in custom else "🔒"
        idx = bank.index(item)
        rows.append([v5_button(f"{mark} {escape(item)[:28]}", f"A16|C|DEL|{key}|{idx}")])
    if len(bank) > 5:
        rows.append([v5_button("بعدی ▶️", f"A16|C|BANK|{key}|5")])
    rows.append([v5_button("➕ افزودن سؤال", f"A16|C|ADD|{key}")])
    rows.append([v5_button("🔙 بانک‌ها", "A16|C|HOME"), v5_button("⌂ خانه", "A16|HOME")])
    label = V7_MODE_LABELS.get(key, key)
    await safe_edit_query(
        query,
        f"📝 <b>{escape(label)}</b>\n______________________\nتعداد: <b>{len(bank)}</b> · ✏️ سفارشی: <b>{len(custom)}</b>\n\n🔒 = اصلی · ✏️ = اضافه‌شده (با لمس حذف می‌شود):",
        v5_markup(rows),
    )


# ----------------------------------------------------------------
# [V16-ADMIN] فلوهای متنی (ورودی‌های پنل) — قبل از روترهای قدیمی
# ----------------------------------------------------------------
async def v16_admin_flow_text(update, context) -> bool:
    user = getattr(update, "effective_user", None)
    msg = getattr(update, "message", None)
    if not user or not msg:
        return False
    uid = int(user.id)
    if not is_admin(uid):
        return False
    text = (msg.text or "").strip()
    flow = A16_FLOW.get(uid)
    if not flow:
        # ورودی متنی منوی مدیریت
        if text in ("👑 مرکز مدیریت", "👑 پنل Super Admin", "👑 Super Admin", "ادمین"):
            if ar12_private_only(update):
                await v16_admin_home_message(update, context)
            else:
                await msg.reply_text("👑 مرکز مدیریت فقط در چت خصوصی ربات است.", reply_markup=ReplyKeyboardRemove())
            return True
        return False
    ftype = flow.get("type")
    try:
        if text in ("لغو", "❌ لغو", "cancel"):
            A16_FLOW.pop(uid, None)
            await msg.reply_text("✅ عملیات لغو شد.")
            return True
        if ftype == "broadcast_text":
            flow["text"] = text
            A16_FLOW[uid] = flow
            await msg.reply_text(
                "📣 <b>پیش‌نمایش پیام</b>\n"
                "______________________\n"
                f"👥 دریافت‌کنندگان: <b>{len(DATA.get('users', {}))}</b> کاربر\n\n"
                "______________________\n"
                f"{escape(text[:1500])}\n"
                "______________________\n"
                "ارسال انجام شود؟",
                parse_mode=ParseMode.HTML,
                reply_markup=v5_markup([
                    [v5_button("🚀 ارسال برای همه", "A16|B|GO")],
                    [v5_button("❌ لغو", "A16|HOME")],
                ]),
            )
            return True
        if ftype == "user_search":
            A16_FLOW.pop(uid, None)
            q = text.lower().strip()
            matches = []
            for k, u in DATA.get("users", {}).items():
                if q == str(k).lower() or q in str(u.get("name", "")).lower():
                    matches.append(int(k))
            if not matches:
                await msg.reply_text("❌ کاربری پیدا نشد.")
                return True
            rows = [[v5_button(f"👤 {escape(get_user(x).get('name', 'کاربر'))[:20]} ({x})", f"A16|U|VIEW|{x}")] for x in matches[:10]]
            rows.append([v5_button("👥 فهرست", "A16|U|PG|0"), v5_button("⌂ خانه", "A16|HOME")])
            await msg.reply_text(f"🔍 <b>نتایج ({len(matches)})</b>:", parse_mode=ParseMode.HTML, reply_markup=v5_markup(rows))
            return True
        if ftype == "user_adjust":
            A16_FLOW.pop(uid, None)
            target = int(flow.get("uid") or 0)
            n = max(0, int(text.replace(",", "")))
            u = get_user(target)
            if flow.get("what") == "xp":
                add_xp(target, n, u.get("name", "کاربر"), 1)
                u["level"] = level_for_xp(int(u.get("xp", 0)))
            else:
                add_coins(target, n, u.get("name", "کاربر"), 1)
            save_data(force=True)
            audit("v16_user_adjust", uid, None, f"{target}:{flow.get('what')}+{n}")
            await msg.reply_text(f"✅ {n} {'XP' if flow.get('what') == 'xp' else 'سکه'} اضافه شد.", parse_mode=ParseMode.HTML, reply_markup=v5_markup([[v5_button("👤 بازگشت به کاربر", f"A16|U|VIEW|{target}")]]))
            return True
        if ftype == "content_add":
            A16_FLOW.pop(uid, None)
            key = str(flow.get("key") or "")
            if v16_add_prompt(key, text):
                audit("v16_prompt_add", uid, None, key)
                await msg.reply_text(
                    f"✅ به بانک «{escape(V7_MODE_LABELS.get(key, key))}» اضافه شد (مجموع: {len(V7_BANKS_FINAL.get(key, []))}).",
                    parse_mode=ParseMode.HTML,
                    reply_markup=v5_markup([[v5_button("📝 مشاهده بانک", f"A16|C|BANK|{key}|0")]]),
                )
            else:
                await msg.reply_text("⚠️ اضافه نشد (خالی یا تکراری).")
            return True
        if ftype == "channel_edit":
            A16_FLOW.pop(uid, None)
            global REQUIRED_CHANNEL, REQUIRED_CHANNEL_URL
            value = text.strip()
            if flow.get("field") == "channel":
                REQUIRED_CHANNEL = _ar8_channel_target(value)
                DATA["settings"]["required_channel"] = REQUIRED_CHANNEL
            else:
                REQUIRED_CHANNEL_URL = value
                DATA["settings"]["required_channel_url"] = value
            APEX_MEMBERSHIP_CACHE.clear()
            save_data(force=True)
            audit("v16_channel_edit", uid, None, value[:80])
            await msg.reply_text("✅ ذخیره شد.", reply_markup=v5_markup([[v5_button("⚙️ تنظیمات", "A16|S|HOME")]]))
            return True
        if ftype == "setting_default":
            A16_FLOW.pop(uid, None)
            val = max(2, min(100, int(text)))
            field = str(flow.get("field") or "")
            DATA["settings"][field] = val
            save_data(force=True)
            audit("v16_setting_default", uid, None, f"{field}={val}")
            await msg.reply_text("✅ ذخیره شد.", reply_markup=v5_markup([[v5_button("⚙️ تنظیمات", "A16|S|HOME")]]))
            return True
    except Exception as exc:
        A16_FLOW.pop(uid, None)
        await msg.reply_text(f"❌ {escape(str(exc))}")
        return True
    return False


# ----------------------------------------------------------------
# [V16-ENTRY] نقاط ورود مدیریت — همه به پنل جدید می‌رسند
