async def ar12_admin_entry(update, context):
    if not ar12_private_only(update):
        msg = getattr(update, "message", None)
        if msg:
            await msg.reply_text("👑 <b>مرکز مدیریت فقط در چت خصوصی Super Admin است.</b>", parse_mode=ParseMode.HTML, reply_markup=ReplyKeyboardRemove())
        return
    await v16_admin_home_message(update, context)


async def v5_admin_home(query):
    await safe_edit_query(query, v16_admin_home_text(), v16_admin_home_markup())


async def ar9_home(query):
    await safe_edit_query(query, v16_admin_home_text(), v16_admin_home_markup())


# ----------------------------------------------------------------
# [V16-GAME] /game با چک حالت بروزرسانی (سایر گیت‌ها از طریق
# ar15_ensure_allowed → ar15_group_gate ما برداشته شده‌اند)
