_AR16_OLD_CREATE_LOBBY = ar15_create_lobby


async def ar15_create_lobby(update, context):
    user = getattr(update, "effective_user", None)
    if user and v16_maintenance() and not is_admin(int(user.id)):
        msg = getattr(update, "message", None)
        if msg:
            await msg.reply_text("🛠 ربات در حال بروزرسانی است؛ چند دقیقه دیگر برگرد.")
        return
    return await _AR16_OLD_CREATE_LOBBY(update, context)


_AR16_OLD_TEXT_ROUTER = ar12_text_router


async def ar12_text_router(update, context):
    try:
        if await v16_admin_flow_text(update, context):
            return
    except Exception as exc:
        print(f"ApexRival V16 admin flow warning: {exc!r}")
    return await _AR16_OLD_TEXT_ROUTER(update, context)


