def ar15_register_handlers(app):
    _AR16_OLD_REGISTER(app)
    # A16| (پنل مدیریت نسل ۱۶) و V16| (جنسیت در گروه) — الگوی اختصاصی،
    # پس هیچ برخوردی با روترهای قدیمی ندارند.
    app.add_handler(CallbackQueryHandler(v16_admin_router, pattern=r"^A16\|"))
    app.add_handler(CallbackQueryHandler(v16_gender_callback, pattern=r"^V16\|G\|"))


