AR16_BOOT_TS = time.time()


def v16_self_check() -> None:
    # 1) بانک‌ها: همه‌ی موضوعات موجود و پر
    required = ["truth", "dare", "secret", "drama", "flirty", "scenario", "mind", "wouldyou", "memory", "relation", "cringe", "adult", "adult_male", "adult_female", "penalty"]
    for key in required:
        bank = V7_BANKS_FINAL.get(key, [])
        assert len(bank) >= 20, f"bank too small: {key} ({len(bank)})"
        assert len(bank) == len(set(bank)), f"duplicates in {key}"
    # 2) برچسب‌ها برای هر ۱۲ موضوع
    for key in required:
        if key not in ("adult_male", "adult_female", "penalty"):
            assert key in V7_MODE_LABELS, f"missing label: {key}"
    # 3) گرید نوبت: پرسشگر باید ۱۲ دکمه‌ی موضوع داشته باشد
    fake_game = {"players": [1, 2, 3], "turn_order": [1, 2, 3], "turn_index": 0, "current_questioner": 1, "turn_number": 1, "round": 0, "round_scores": {}}
    markup = v7_turn_markup(fake_game, 1)
    mode_buttons = []
    for row in getattr(markup, "inline_keyboard", []):
        for b in row:
            data = getattr(b, "callback_data", None)
            if data is not None:
                assert len(str(data).encode("utf-8")) <= 64, data
                if str(data).startswith("V7|MODE|"):
                    mode_buttons.append(str(data).split("|")[2])
    assert len(mode_buttons) == 12, f"expected 12 mode buttons, got {len(mode_buttons)}"
    for key in ("truth", "dare", "secret", "drama", "flirty", "scenario", "mind", "wouldyou", "memory", "relation", "cringe", "adult"):
        assert key in mode_buttons, f"mode button missing: {key}"
    # 4) پنل ادمین: همه‌ی بخش‌ها markup غیرخالی دارند
    assert v16_admin_home_markup() is not None
    body, mk = v16_users_page(0)
    assert mk is not None and body
    # 5) گیت پیش‌فرض باز
    assert ar16_gate_mode() == "off"
    # 6) کیبورد A16 و V16 الگوی اختصاصی دارند
    sample = "A16|U|VIEW|123456789"
    assert len(sample.encode("utf-8")) <= 64
    # 7) اجرای سلف-چک‌های قدیمی برای اطمینان از سلامت زنجیره‌ها
    v7_runtime_self_check()
    print(
        f"ApexRival V16 self-check OK | banks={len(V7_BANKS_FINAL)} | "
        f"prompts={sum(len(v) for v in V7_BANKS_FINAL.values())} | modes=12 | "
        f"admin=A16 | lobby-join=open | adult-gate=one-time"
    )


v16_self_check()




