_AR18_OLD_TURN_MARKUP = v7_turn_markup


def v7_turn_markup(game, viewer_uid):
    q = v7_current_questioner(game)
    if q is None:
        return v5_markup([v5_nav("V5|GAME")])
    if int(viewer_uid) == int(q):
        rows = []
        pair = []
        for key, label in v18_topic_buttons():
            pair.append(v5_button(label, f"V7|MODE|{key}"))
            if len(pair) == 2:
                rows.append(pair)
                pair = []
        if pair:
            rows.append(pair)
        rows.append([v5_button("🎲 تغییر نوبت", "V7|SKIP"), v5_button("ℹ️ راهنما", "V7|HELP")])
        rows.append(ar7_game_nav("V5|GAME"))
    else:
        rows = [
            [v5_button("📊 وضعیت نوبت", "V7|TURN")],
            [v5_button("☠️ حکم من", "V7|PENALTY"), v5_button("🏆 امتیازها", "V7|SCORES")],
            [v5_button("ℹ️ راهنما", "V7|HELP")],
            ar7_game_nav("V5|GAME"),
        ]
    return v5_markup(rows)


_AR18_OLD_TURN_CARD = v7_turn_card


def v7_turn_card(game):
    base = _AR18_OLD_TURN_CARD(game)
    try:
        heat = v18_game_heat(game)
        base = (
            f"{base}\n"
            f"🌡 گرمای بازی: <b>{v18_heat_chip(heat)}</b> — سوال‌ها با پیشرفت بازی داغ‌تر می‌شوند"
        )
    except Exception:
        pass
    return base


