# ----------------------------------------------------------------
# [V19-REGISTER] ثبت هندلرهای V19 روی اپلیکیشن اصلی
# ----------------------------------------------------------------
def v19_register_handlers(app) -> None:
    try:
        V19_BOOT["app"] = app
        try:
            V19_BOOT["bot"] = app.bot
        except Exception:
            pass
        # محافظ اسپم — قبل از همه (گروه -۹۷)
        try:
            app.add_handler(CallbackQueryHandler(v19_rate_guard_callback, pattern=r""), group=-97)
        except Exception:
            pass
        try:
            app.add_handler(MessageHandler(filters.COMMAND, v19_rate_guard_command), group=-97)
        except Exception:
            pass
        # خوش‌آمدگویی — قبل از روترهای اصلی (گروه -۹۰)
        try:
            app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, v19_welcome_new_member), group=-90)
        except Exception:
            pass
        # روتر دکمه‌های V19 — الگوی اختصاصی، بدون تداخل
        try:
            app.add_handler(CallbackQueryHandler(v19_callback_router, pattern=r"^V19\|"))
        except Exception:
            pass
        # دستورات اختصاصی جدید
        try:
            app.add_handler(CommandHandler("apexprofile", v19_cmd_profile))
            app.add_handler(CommandHandler("apextop", v19_cmd_top))
            app.add_handler(CommandHandler("apexguide", v19_cmd_guide))
            app.add_handler(CommandHandler("apexmute", v19_cmd_mute))
            app.add_handler(CommandHandler("apexunmute", v19_cmd_unmute))
        except Exception:
            pass
    except Exception as exc:
        try:
            print(f"ApexRival V19 register warning: {exc!r}")
        except Exception:
            pass


_AR19_OLD_REGISTER = ar15_register_handlers


def ar15_register_handlers(app):
    _AR19_OLD_REGISTER(app)
    v19_register_handlers(app)


# ----------------------------------------------------------------
# [V19-BOOT] post_init: مسلح‌کردن دوباره نگهبانان + آمار بوت
# ----------------------------------------------------------------
_AR19_OLD_POST_INIT = ar15_post_init


async def ar15_post_init(application):
    await _AR19_OLD_POST_INIT(application)
    try:
        V19_BOOT["app"] = application
        try:
            V19_BOOT["bot"] = application.bot
        except Exception:
            pass
        V19_BOOT["boot_ts"] = now_ts()
        armed = v19_rearm_stalls()
        try:
            app_ref = application
            app_ref.create_task(v19_rearm_report(armed))
        except Exception:
            print(f"ApexRival V19 boot | stall-guards re-armed: {armed}")
    except Exception as exc:
        try:
            print(f"ApexRival V19 post-init warning: {exc!r}")
        except Exception:
            pass


async def v19_rearm_report(armed: int) -> None:
    try:
        print(
            f"ApexRival V19 ULTRA layer online | smart-mentions=on | "
            f"anti-spam=on | stall-guard=on | weekly-board=on | profile2=on | "
            f"guide=on | welcome=on | quiet-hours=on | new-prompts={sum(_V19_EXPAND_REPORT.values())} | "
            f"stall-guards-armed={armed}"
        )
    except Exception:
        pass


# ----------------------------------------------------------------
# [V19-CHECK] سلف-چک لایه — هنگام لود اجرا می‌شود
# ----------------------------------------------------------------
def v19_self_check() -> None:
    # ۱) همه‌ی توابع کلیدی تعریف شده‌اند
    for fn in (
        v19_cfg, v19_prefs, v19_wants_mentions, v19_mention,
        v19_rate_hit, v19_rate_guard_callback, v19_rate_guard_command,
        v19_quiet_now, v19_stall_cancel, v19_stall_arm, v19_stall_watch,
        v19_auto_skip, v19_rearm_stalls, v19_week_key, v19_track_weekly,
        v19_week_top, v19_alltime_top, v19_board_text, v19_note_levelup,
        v19_celebrate_levelup, v19_profile_text, v19_xp_bar, v19_guide_text,
        v19_guide_markup, v19_welcome_new_member, v19_cmd_profile, v19_cmd_top,
        v19_cmd_guide, v19_cmd_mute, v19_cmd_unmute, v19_callback_router,
        v19_set_text, v19_set_markup, v19_register_handlers,
        v19_expand_banks, v19_send_group,
    ):
        assert callable(fn), f"v19 missing function: {getattr(fn, '__name__', fn)}"
    # ۲) محتوای جدید واقعاً اضافه شده (بعد از دی‌داپ)
    assert isinstance(_V19_EXPAND_REPORT, dict) and len(_V19_EXPAND_REPORT) >= 14
    total_new = sum(_V19_EXPAND_REPORT.values())
    assert total_new >= 300, f"v19 bank expansion too small: {total_new}"
    for key in ("truth_deep", "dare_deep", "secret_deep", "drama", "flirty", "scenario", "mind",
                "wouldyou", "memory", "relation", "cringe", "adult", "dream",
                "regret", "future", "penalty"):
        if key not in _V19_EXPAND_REPORT:
            alias = {"truth_deep": "truth", "dare_deep": "dare", "secret_deep": "secret"}.get(key, key)
            assert alias in _V19_EXPAND_REPORT, f"v19 bank missing report: {key}"
        bank = V18_FACTORY.get(key, [])
        assert len(bank) >= 20, f"v19 factory bank too small: {key}"
        assert len(bank) == len(set(str(x) for x in bank)), f"v19 factory duplicates: {key}"
    # ۳) کاربر mute شده → بدون لینک؛ unmute → با لینک
    probe_uid = 987654321
    v19_prefs(probe_uid)["mentions"] = False
    plain = mention_user(probe_uid, "ProbeName")
    assert "tg://user" not in str(plain) and "ProbeName" in str(plain)
    v19_prefs(probe_uid)["mentions"] = True
    linked = mention_user(probe_uid, "ProbeName")
    assert "tg://user" in str(linked)
    # پاک‌سازی پروب
    try:
        v19_store()["prefs"].pop(user_key(probe_uid), None)
    except Exception:
        pass
    # ۴) الگوی callbackها کوتاه و معتبر (≤ ۶۴ بایت)
    for sample in (
        "V19|GUI|0", "V19|GUI|7", "V19|GUI|DONE", "V19|TOP|W", "V19|TOP|A",
        "V19|MUTE|TO", "V19|SET|HOME", "V19|SET|ST", "V19|SET|WL",
        "V19|SET|QH", "V19|SET|RL", "V19|SET|RMIN|P", "V19|SET|RMIN|B",
        "V19|SET|SMIN|P", "V19|SET|QF|P", "V19|SET|QT|B", "V19|SET|NOP",
    ):
        assert 1 <= len(sample.encode("utf-8")) <= 64, sample
        assert sample.count("|") >= 2 and sample.startswith("V19|"), sample
    # ۵) راهنمای تعاملی سالم
    assert len(V19_GUIDE_PAGES) == 8
    for idx in range(len(V19_GUIDE_PAGES)):
        t = v19_guide_text(idx)
        assert t and "راهنمای ApexRival" in t and f"صفحه {idx + 1} از 8" in t
    assert v19_guide_markup(3) is not None
    # ۶) رتبه‌بندی هفتگی و دفتر
    wk = v19_week_key()
    assert isinstance(wk, str) and wk
    v19_track_weekly(123456789, 5, "Probe")
    probe_rows = [r for r in v19_week_top(50) if int(r[1]) == 123456789]
    assert probe_rows and int(probe_rows[0][0]) >= 5
    rows = v19_week_top(10)
    txt = v19_board_text(rows, "W")
    assert "قهرمانان این هفته" in txt
    txt2 = v19_board_text(v19_alltime_top(5), "A")
    assert "همه‌ی زمان‌ها" in txt2
    # پاک‌سازی پروب‌های آمار
    try:
        v19_store()["weekly"].get(wk, {}).pop(user_key(123456789), None)
        v19_store()["weekly"].get(wk, {}).pop(user_key(987654321), None)
    except Exception:
        pass
    # ۷) پروفایل کامل رندر می‌شود (پروبِ موقت با XP؛ اگر کاربرِ واقعی بود
    #    مقدار قبلی‌اش دقیقاً برمی‌گردد تا داده‌ی واقعی دست‌نخورده بماند)
    _p7_uid = 123456789
    _p7_existed = user_key(_p7_uid) in DATA.get("users", {})
    _p7_xp_before = int(get_user(_p7_uid).get("xp", 0) or 0)
    try:
        add_xp(_p7_uid, 137, "ProbeProfile")
    except Exception:
        pass
    ptxt = v19_profile_text(_p7_uid)
    assert "پروفایل ApexRival" in ptxt and "تا سطح" in ptxt and "▓" in ptxt
    # قلابِ ارتقای سطح هم کار کرده باشد
    assert v19_take_levelup(_p7_uid) is not None
    # پاک‌سازی کاملِ ردپای پروب
    try:
        v19_store()["weekly"].get(v19_week_key(), {}).pop(user_key(_p7_uid), None)
        v19_store()["lvl_pending"].pop(user_key(_p7_uid), None)
        if _p7_existed:
            _p7_u = get_user(_p7_uid)
            _p7_u["xp"] = _p7_xp_before
            _p7_u["level"] = level_for_xp(_p7_xp_before)
        else:
            DATA.get("users", {}).pop(user_key(_p7_uid), None)
    except Exception:
        pass
    # ۸) تنظیمات: مقادیر پیش‌فرض و گیرها
    probe_gid = -100999
    cfg = v19_cfg(probe_gid)
    assert cfg["stall"] is True and cfg["rmin"] >= 1 and cfg["smin"] > cfg["rmin"]
    assert v19_quiet_now(probe_gid) is False  # خاموش پیش‌فرض
    cfg2 = dict(cfg)
    cfg2["quiet_on"] = True
    v19_save_cfg(probe_gid, cfg2)
    assert isinstance(v19_quiet_now(probe_gid), bool)
    # پاک‌سازی گروهِ پروب از مخزن پایدار
    try:
        v19_store()["cfg"].pop(group_key(probe_gid), None)
    except Exception:
        pass
    # ۹) محافظ اسپم: آستانه‌های معتبر
    for lvl, (c, m) in V19_RATE_LIMITS.items():
        assert 1 <= c <= 50 and 1 <= m <= 50
    assert v19_rate_hit(987654000, "callback", 0) in (True, False)
    # ۱۰) دستورات جدید ثبت‌شده در گیت و منو
    for cmd in ("apexprofile", "apextop", "apexguide", "apexmute", "apexunmute"):
        assert cmd in V17_UNIQUE_COMMANDS, f"gate missing: {cmd}"
        assert 1 <= len(cmd) <= 32 and cmd.isascii() and cmd.islower(), cmd
    menu_names = [str(c.command) for c in V17_COMMAND_MENU]
    for cmd in ("apex", "apexprofile", "apextop", "apexguide", "apexmute", "start", "help"):
        assert cmd in menu_names, f"menu missing: {cmd}"
    assert menu_names[0] == "apex"
    # ۱۱) قلاب‌ها واقعاً نصب شده‌اند
    assert add_xp.__name__ != "_AR19_OLD_ADD_XP" and callable(_AR19_OLD_ADD_XP)
    assert v7_turn_announcement.__name__ == "v7_turn_announcement"
    assert callable(_AR19_OLD_TURN_ANNOUNCE)
    assert callable(_AR19_OLD_ENDGAME) and callable(_AR19_OLD_REPLY)
    assert callable(_AR19_OLD_REGISTER) and callable(_AR19_OLD_POST_INIT)
    assert callable(_AR19_OLD_ADMIN_HOME) and callable(_AR19_OLD_MENTION)
    assert v16_admin_home_markup() is not None
    # ۱۲) مرکز راهنما گسترش یافته
    assert len(V18_HELP_CENTER_EXTRA) >= 5
    print(
        f"ApexRival V19 self-check OK | new-prompts={total_new} | "
        "smart-mentions=on | anti-spam=on | stall-guard=on | weekly=on | "
        "profile2=on | guide=on | welcome=on | settings-panel=on"
    )


# ================================================================
# [V20-SANITIZE] ضد آجرِ ری‌استارت — قبل از سلف‌چک V19 اجرا می‌شود.
# سلف‌چک V19 پروبِ تنظیمات گروه ساختگی‌اش (g-100999) را ذخیره می‌کند و
# بعد فقط از «حافظه» پاپ می‌کند؛ اگر ذخیره‌ی نهایی انجام نشود، فایل
# game_data.json کثیف می‌ماند و بوتِ بعدی همان‌جا assert می‌خورد و
# می‌شکند. این بلوک پروب‌های ساختگی را قبل از اجرای سلف‌چک‌ها از مخزن
# پایدار پاک و ذخیره می‌کند تا هر ری‌استارتی سالم بالا بیاید.
# (صددرصد افزودنی — هیچ خطی تغییر نمی‌کند.)
# ================================================================
try:
    _V20_SAN_CHANGED = False
    _V20_SAN_V19CFG = DATA.get("v19", {}).get("cfg", {}) if isinstance(DATA, dict) else None
    if isinstance(_V20_SAN_V19CFG, dict):
        _V20_SAN_GK = group_key(-100999)
        if _V20_SAN_GK in _V20_SAN_V19CFG:
            _V20_SAN_V19CFG.pop(_V20_SAN_GK, None)
            _V20_SAN_CHANGED = True
    _V20_SAN_V20 = DATA.get("v20", {}) if isinstance(DATA, dict) else None
    if isinstance(_V20_SAN_V20, dict):
        for _V20_SAN_SEC in ("gcfg", "teams", "daily", "gstats"):
            _V20_SAN_MAP = _V20_SAN_V20.get(_V20_SAN_SEC)
            if isinstance(_V20_SAN_MAP, dict):
                for _V20_SAN_PID in (-100770, -100771, -100772, -100773, -100774, -100999):
                    _V20_SAN_KEY = group_key(_V20_SAN_PID)
                    if _V20_SAN_KEY in _V20_SAN_MAP:
                        _V20_SAN_MAP.pop(_V20_SAN_KEY, None)
                        _V20_SAN_CHANGED = True
    if _V20_SAN_CHANGED:
        save_data(force=True)
except Exception:
    pass



v19_self_check()



# ================================================================
# [V20-LAYER] ApexRival V20 MEGA UX + GROUP LAYER
# ================================================================
# پنل‌های هوشمند V20:
#   ۱) وقتی منوی جدید باز می‌شود، پنل قبلیِ همان کاربر «بسته و حذف»
#      می‌شود — در چت خصوصی و در گروه‌ها، برای «همه‌ی» منوها.
#   ۲) دکمه‌ی «⬅️ بازگشت» و «✖️ بستن» به تک‌تک منوها و مسیرها اضافه
#      می‌شود؛ حافظه‌ی ناوبری هر پنل، مسیر را مرحله‌به‌مرحله برمی‌گرداند.
#   ۳) پیام دستورِ کاربر (مثل /start) پاک می‌شود تا گروه تمیز بماند.
#   ۴) پنل‌های کهنه بعد از ساعت‌ها خودکار «منقضی» می‌شوند (دکمه‌ها
#      برمی‌داریم تا دکمه‌ی مرده در چت نماند).
#   ۵) دکمه‌ی ✕ بستنِ منوهای V5 حالا پیام را واقعاً «حذف» می‌کند.
#   به‌علاوه: تیم‌های رقابتی، چالش روزانه‌ی گروه، قلب محبت،
#   «موقتاً نیستم»، گزارش هفتگی گروه، جشن دهمین بازی و +۱۶۰ پرامپت تازه.
# صددرصد افزودنی — هیچ خطی از نسخه‌های قبل حذف یا تغییر نمی‌کند.
# ================================================================

# ----------------------------------------------------------------
# [V20-IMPORT] ایمپورت‌های دفاعی — اگر نسخه‌ی کتابخانه فرق کند کرش نمی‌کند
# ----------------------------------------------------------------
try:
    import contextvars as _v20_cv
except Exception:
    _v20_cv = None

try:
    from telegram.ext import TypeHandler as _V20_TypeHandler
except Exception:
    _V20_TypeHandler = None

try:
    from telegram.ext import ApplicationHandlerStop as _V20_AHS
except Exception:
    _V20_AHS = None


# ----------------------------------------------------------------
# [V20-STATE] وضعیت لحظه‌ای پنل‌ها (در ری‌استارت خالی شروع می‌شود؛
# داده‌های ماندگار مثل تنظیمات/تیم‌ها داخل DATA["v20"] ذخیره می‌شوند)
# ----------------------------------------------------------------
V20_BOOT: dict = {"app": None, "bot": None, "prune_task": None, "boot_ts": 0}
V20_PANELS: dict = {}    # (chat_id, uid) -> [message_id, ...] پنل‌های فعال کاربر
V20_NAV: dict = {}       # (chat_id, message_id) -> {"owner", "stack": [state...], "ts"}
V20_PENDING: dict = {}   # (chat_id, uid) -> {"ids": [...], "ts"} — پنل‌هایی که با منوی جدید حذف می‌شوند
_V20_CTX = None
if _v20_cv is not None:
    try:
        _V20_CTX = _v20_cv.ContextVar("apexrival_v20_ctx")
    except Exception:
        _V20_CTX = None
_V20_PM_UNSET = object()   # نشانگرِ «parse_mode داده نشده»
_V20_PANELS_ENABLED = str(os.getenv("APEX_V20_PANELS", "1") or "1").strip().lower() not in ("0", "off", "false", "no")


def v20_now() -> float:
    try:
        return float(time.time())
    except Exception:
        return 0.0


def v20_day_key(ts: float | None = None) -> str:
    try:
        return time.strftime("%Y-%m-%d", time.gmtime(ts if ts is not None else v20_now()))
    except Exception:
        return "1970-01-01"


def v20_ctx_get():
    if _V20_CTX is None:
        return None
    try:
        return _V20_CTX.get()
    except Exception:
        return None


def v20_ctx_set(value) -> None:
    if _V20_CTX is None:
        return
    try:
        _V20_CTX.set(value)
    except Exception:
        pass


def v20_store() -> dict:
    """مخزن پایدار V20 داخل DATA — با ری‌استارت نمی‌پرد."""
    try:
        s = DATA.setdefault("v20", {})
    except Exception:
        return {}
    s.setdefault("gcfg", {})
    s.setdefault("teams", {})
    s.setdefault("daily", {})
    s.setdefault("hearts", {})
    s.setdefault("brb", {})
    s.setdefault("gstats", {})
    return s


# ----------------------------------------------------------------
# [V20-CFG] تنظیمات هر چت (گروه یا خصوصی) — همه با پیش‌فرض امن
# ----------------------------------------------------------------
V20_GCFG_DEFAULTS = {
    "back": True,        # دکمه‌ی برگشت/بستن به منوها اضافه شود؟
    "delcmd": True,      # پیام دستورِ کاربر (مثل /start) پاک شود؟
    "stale": True,       # پنل‌های کهنه خودکار منقضی شوند؟
    "stale_h": 12,       # بعد از چند ساعت؟
    "pmax": 6,           # حداکثر پنل فعالِ هم‌زمان برای هر کاربر
    "teams": True,       # تیم‌های رقابتی فعال؟
    "daily": True,       # چالش روزانه‌ی گروه فعال؟
    "daily_goal": 25,    # هدف نوبت‌های روزانه
}


def v20_gcfg(chat_id: int) -> dict:
    """تنظیمات چت با merge روی پیش‌فرض‌ها."""
    try:
        all_cfg = v20_store()["gcfg"]
        cfg = dict(V20_GCFG_DEFAULTS)
        raw = all_cfg.get(group_key(int(chat_id)), {})
        if isinstance(raw, dict):
            for k, v in raw.items():
                if k in V20_GCFG_DEFAULTS:
                    cfg[k] = v
        cfg["stale_h"] = max(1, int(cfg.get("stale_h", 12) or 12))
        cfg["pmax"] = max(1, min(12, int(cfg.get("pmax", 6) or 6)))
        cfg["daily_goal"] = max(5, min(500, int(cfg.get("daily_goal", 25) or 25)))
        return cfg
    except Exception:
        return dict(V20_GCFG_DEFAULTS)


def v20_save_cfg(chat_id: int, cfg: dict) -> None:
    try:
        v20_store()["gcfg"][group_key(int(chat_id))] = {
            k: cfg.get(k, V20_GCFG_DEFAULTS.get(k)) for k in V20_GCFG_DEFAULTS
        }
        save_data(force=True)
    except Exception:
        pass


# ----------------------------------------------------------------
# [V20-WHITELIST] دستوراتی که «منو» باز می‌کنند — در گروه فقط این‌ها
# پنل می‌سازند که مدیریت پنل رویشان فعال شود (جریان بازی دست‌نخورده می‌ماند)
# ----------------------------------------------------------------
V20_GROUP_MENU_CMDS = {
    "start", "help", "profile", "rank", "shop", "menu", "stats",
    "apexhelp", "apexstats", "apexid", "apexpanel",
    "apexprofile", "apextop", "apexguide", "apexmute", "apexunmute",
    "apexteams", "apexdaily", "apexrecap",
}

# واژه‌هایی که اگر در دکمه‌های یک منو بودند، یعنی ناوبری خودش را دارد
V20_NAV_WORDS = ("بازگشت", "بستن", "خانه", "⌂", "⬅", "🔙")


# ----------------------------------------------------------------
# [V20-DECORATE] دکمه‌ی برگشت/بستن — به هر منویی که ناوبری ندارد
# ----------------------------------------------------------------
def v20_decorate_markup(markup, *, depth: int, is_home: bool):
    """یک ردیف ناوبری به کیبورد منو اضافه می‌کند (اگر لازم باشد).
    - عمق ۱ و خانه‌ی اصلی → فقط «✖️ بستن»
    - عمق ۱ و زیرمنو → «🏠 منوی اصلی» + «✖️ بستن»
    - عمق ≥ ۲ → «⬅️ بازگشت» + «✖️ بستن»
    منوهایی که خودشان دکمه‌ی برگشت/خانه/بستن دارند دست نمی‌خورند."""
    try:
        if markup is None or not isinstance(markup, InlineKeyboardMarkup):
            return markup
        rows = [[b for b in row] for row in markup.inline_keyboard]
        if not rows:
            return markup
        joined = " ".join(
            str(getattr(b, "text", "") or "") for row in rows for b in row
        )
        if any(word in joined for word in V20_NAV_WORDS):
            return markup
        depth = max(1, int(depth or 1))
        if depth <= 1:
            if is_home:
                extra = [v5_button("✖️ بستن پنل", "V20|CL")]
            else:
                extra = [v5_button("🏠 منوی اصلی", "V20|HM"), v5_button("✖️ بستن", "V20|CL")]
        else:
            extra = [v5_button("⬅️ بازگشت", "V20|BK"), v5_button("✖️ بستن", "V20|CL")]
        rows.append(extra)
        return v5_markup(rows)
    except Exception:
        return markup


def v20_home_state(uid: int) -> dict:
    """خانه‌ی اصلیِ ناوبری — همان کارت قهرمانِ منوی خصوصی."""
    try:
        return {
            "text": ar12_private_home_text(int(uid)),
            "parse_mode": ParseMode.HTML,
            "markup": ar12_private_home_markup(int(uid)),
            "home": True,
            "ts": v20_now(),
        }
    except Exception:
        return {
            "text": "🎮 منوی ApexRival — /start",
            "parse_mode": _V20_PM_UNSET,
            "markup": None,
            "home": True,
            "ts": v20_now(),
        }


# ----------------------------------------------------------------
# [V20-PENDING] پاک‌سازی تنبلِ پنل‌های معوق (TTL کوتاه)
# ----------------------------------------------------------------
def v20_prune_pending() -> None:
    try:
        now = v20_now()
        for key in list(V20_PENDING.keys()):
            ent = V20_PENDING.get(key)
            if not isinstance(ent, dict) or now - float(ent.get("ts", 0) or 0) > 90:
                V20_PENDING.pop(key, None)
    except Exception:
        pass


def v20_forget_panel(chat_id: int, message_id: int, owner: int = 0) -> None:
    """ردیابی یک پیام پنل را کامل برمی‌دارد."""
    try:
        nav = V20_NAV.pop((int(chat_id), int(message_id)), None)
        own = int(owner or (nav.get("owner", 0) if isinstance(nav, dict) else 0) or 0)
        if own:
            lst = V20_PANELS.get((int(chat_id), own))
            if isinstance(lst, list):
                try:
                    lst.remove(int(message_id))
                except Exception:
                    pass
    except Exception:
        pass


# ----------------------------------------------------------------
# [V20-SNIFFER] پیش از همه‌ی هندلرها: عاملِ این آپدیت را ثبت می‌کند
# (خصوصی: همه‌ی آپدیت‌ها منو-محورند؛ گروه: فقط دستورهای منویی)
# و پیام دستور را برای تمیز ماندن چت پاک می‌کند.
# ----------------------------------------------------------------
async def v20_menu_sniffer(update, context) -> None:
    try:
        chat = getattr(update, "effective_chat", None)
        user = getattr(update, "effective_user", None)
        if chat is None or user is None:
            return
        if getattr(user, "is_bot", False):
            return
        ctype = str(getattr(chat, "type", "") or "")
        cid = int(getattr(chat, "id", 0) or 0)
        uid = int(getattr(user, "id", 0) or 0)
        # توجه: id چتِ گروه‌ها در تلگرام «منفی» است؛ فقط صفر نامعتبر است
        if cid == 0 or uid <= 0:
            return
        msg = getattr(update, "message", None) or getattr(update, "edited_message", None)
        cmd = ""
        if msg is not None:
            text = str(getattr(msg, "text", "") or "")
            if text.startswith("/"):
                try:
                    cmd = text.split()[0].lstrip("/").split("@", 1)[0].lower()
                except Exception:
                    cmd = ""
        if ctype == "private":
            menu_cmd = True
        elif ctype in ("group", "supergroup"):
            menu_cmd = bool(cmd) and cmd in V20_GROUP_MENU_CMDS
        else:
            menu_cmd = False
        if not menu_cmd:
            return
        v20_ctx_set({"chat": cid, "uid": uid, "cmd": cmd, "menu": True, "ts": v20_now()})
        v20_prune_pending()
        ids = [int(x) for x in V20_PANELS.get((cid, uid), []) if int(x or 0) > 0]
        if ids:
            V20_PENDING[(cid, uid)] = {"ids": ids, "ts": v20_now()}
        # پاک‌کردن پیام دستور (ضد شلوغی) — فقط با اجازه‌ی تنظیمات و بی‌صدا
        try:
            g = v20_gcfg(cid)
            delcmd = bool(g.get("delcmd", True))
        except Exception:
            delcmd = True
        if delcmd and cmd and msg is not None and getattr(update, "message", None) is not None:
            bot = getattr(context, "bot", None)
            if bot is not None:
                mid = int(getattr(msg, "message_id", 0) or 0)
                if mid > 0:
                    try:
                        await bot.delete_message(chat_id=cid, message_id=mid)
                    except Exception:
                        pass
    except Exception as exc:
        try:
            print(f"ApexRival V20 sniffer warning: {exc!r}")
        except Exception:
            pass


# ----------------------------------------------------------------
# [V20-SEND/EDIT] قلاب امن روی Bot.send_message / Bot.edit_message_text
# هر ۳۰۰+ نقطه‌ی ارسالِ منو در کل فایل — بدون تغییر حتی یک خط — از
# این دو قلاب رد می‌شوند؛ در محیط تست فقط وقتی Bot واقعی صدا زده شود.
# ----------------------------------------------------------------
async def v20_after_send(bot, chat_id: int, owner: int, result, *, text, parse_mode, markup, cmd) -> None:
    """بعد از ارسال موفق منو: پنل‌های قبلی حذف + ثبت پنل جدید + حافظه‌ی ناوبری."""
    mid = int(getattr(result, "message_id", 0) or 0)
    if mid <= 0:
        return
    key = (int(chat_id), int(owner))
    # ۱) پنل‌های قبلیِ همان کاربر را ببند و حذف کن (قلبِ رفع باگ)
    pend = V20_PENDING.pop(key, None)
    if isinstance(pend, dict):
        for old_mid in [int(x) for x in pend.get("ids", [])]:
            if old_mid > 0 and old_mid != mid:
                try:
                    await bot.delete_message(chat_id=int(chat_id), message_id=old_mid)
                except Exception:
                    pass
                v20_forget_panel(int(chat_id), old_mid)
    # ۲) ثبت پنل جدید
    try:
        pmax = max(1, int(v20_gcfg(int(chat_id)).get("pmax", 6)))
    except Exception:
        pmax = 6
    lst = V20_PANELS.setdefault(key, [])
    lst.append(mid)
    if len(lst) > pmax:
        del lst[: len(lst) - pmax]
    # ۳) حافظه‌ی ناوبری
    V20_NAV[(int(chat_id), mid)] = {
        "owner": int(owner),
        "stack": [{
            "text": str(text or ""),
            "parse_mode": parse_mode,
            "markup": markup,
            "home": bool(cmd == "start"),
            "ts": v20_now(),
        }],
        "ts": v20_now(),
    }
    v20_cap_nav()


def v20_cap_nav(limit: int = 400) -> None:
    try:
        if len(V20_NAV) <= limit:
            return
        items = sorted(V20_NAV.items(), key=lambda kv: float(kv[1].get("ts", 0) or 0))
        for k, _ in items[: max(0, len(V20_NAV) - limit)]:
            V20_NAV.pop(k, None)
    except Exception:
        pass


async def v20_bot_send_message(self, *args, **kwargs):
    """پوشش Bot.send_message — منوها را تزئین، ردیابی و یکتا می‌کند."""
    send_key = None
    owner = 0
    chat_id = 0
    markup = None
    text = ""
    pm = _V20_PM_UNSET
    cmd = ""
    try:
        if not _V20_PANELS_ENABLED:
            return await _V20_ORIG_SEND(self, *args, **kwargs)
        chat_id = kwargs.get("chat_id", args[0] if len(args) >= 1 else None)
        text = kwargs.get("text", args[1] if len(args) >= 2 else None)
        markup = kwargs.get("reply_markup")
        pm = kwargs.get("parse_mode", _V20_PM_UNSET)
        ctx = v20_ctx_get()
        if isinstance(chat_id, int) and not isinstance(chat_id, bool):
            chat_id = int(chat_id)
            owner = 0
            if ctx is not None and bool(ctx.get("menu")):
                try:
                    if int(ctx.get("chat", 0) or 0) == chat_id:
                        owner = int(ctx.get("uid", 0) or 0)
                        if chat_id > 0 and owner <= 0:
                            owner = chat_id
                except Exception:
                    owner = 0
            if owner > 0 and markup is not None and isinstance(markup, InlineKeyboardMarkup):
                cmd = str((ctx or {}).get("cmd", "") or "")
                decorate = True
                if chat_id < 0:
                    try:
                        decorate = bool(v20_gcfg(chat_id).get("back", True))
                    except Exception:
                        decorate = True
                if decorate:
                    dec = v20_decorate_markup(markup, depth=1, is_home=(cmd == "start"))
                    if dec is not markup:
                        kwargs["reply_markup"] = dec
                send_key = (int(chat_id), int(owner))
    except Exception:
        send_key = None
    result = await _V20_ORIG_SEND(self, *args, **kwargs)
    if send_key is not None:
        try:
            await v20_after_send(
                self, send_key[0], send_key[1], result,
                text=text, parse_mode=pm, markup=markup, cmd=cmd,
            )
        except Exception:
            pass
    return result


async def v20_bot_edit_text(self, *args, **kwargs):
    """پوشش Bot.edit_message_text — ناوبریِ منوهای ادیت‌شونده را ضبط می‌کند."""
    mode = 0            # 0=خاموش، 1=ادامه‌ی ناوبری، 2=پایان پنل، 3=به‌دست‌گرفتن پنل خصوصی
    e_key = None
    e_text = ""
    e_pm = _V20_PM_UNSET
    e_markup = None
    try:
        if not _V20_PANELS_ENABLED:
            return await _V20_ORIG_EDIT(self, *args, **kwargs)
        text = kwargs.get("text", args[0] if len(args) >= 1 else None)
        chat_id = kwargs.get("chat_id", args[1] if len(args) >= 2 else None)
        message_id = kwargs.get("message_id", args[2] if len(args) >= 3 else None)
        markup = kwargs.get("reply_markup")
        e_pm = kwargs.get("parse_mode", _V20_PM_UNSET)
        e_text = text
        e_markup = markup
        if isinstance(chat_id, int) and isinstance(message_id, int):
            chat_id = int(chat_id)
            message_id = int(message_id)
            key = (chat_id, message_id)
            nav = V20_NAV.get(key)
            if nav is not None:
                if markup is not None and isinstance(markup, InlineKeyboardMarkup):
                    decorate = True
                    if chat_id < 0:
                        try:
                            decorate = bool(v20_gcfg(chat_id).get("back", True))
                        except Exception:
                            decorate = True
                    if decorate:
                        dec = v20_decorate_markup(markup, depth=len(nav.get("stack", [])) + 1, is_home=False)
                        if dec is not markup:
                            kwargs["reply_markup"] = dec
                    mode = 1
                    e_key = key
                else:
                    # منو بدون دکمه ادیت شد → پنل بسته شده است
                    mode = 2
                    e_key = key
            elif chat_id > 0 and markup is not None and isinstance(markup, InlineKeyboardMarkup):
                # چت خصوصی: هر ادیتِ کیبوردی، پنلِ همین کاربر است → به دست می‌گیریم
                mode = 3
                e_key = key
    except Exception:
        mode = 0
        e_key = None
    result = await _V20_ORIG_EDIT(self, *args, **kwargs)
    try:
        if e_key is None:
            return result
        chat_id, message_id = int(e_key[0]), int(e_key[1])
        if mode == 1:
            nav = V20_NAV.get(e_key)
            if isinstance(nav, dict):
                stack = nav.setdefault("stack", [])
                stack.append({
                    "text": str(e_text or ""),
                    "parse_mode": e_pm,
                    "markup": e_markup,
                    "home": False,
                    "ts": v20_now(),
                })
                if len(stack) > 16:
                    del stack[: len(stack) - 16]
                nav["ts"] = v20_now()
        elif mode == 2:
            v20_forget_panel(chat_id, message_id)
        elif mode == 3:
            owner = chat_id
            try:
                pmax = max(1, int(v20_gcfg(chat_id).get("pmax", 6)))
            except Exception:
                pmax = 6
            lst = V20_PANELS.setdefault((chat_id, owner), [])
            if message_id not in lst:
                lst.append(message_id)
            if len(lst) > pmax:
                del lst[: len(lst) - pmax]
            V20_NAV[(chat_id, message_id)] = {
                "owner": owner,
                "stack": [{
                    "text": str(e_text or ""),
                    "parse_mode": e_pm,
                    "markup": e_markup,
                    "home": False,
                    "ts": v20_now(),
                }],
                "ts": v20_now(),
            }
            v20_cap_nav()
    except Exception:
        pass
    return result


# ----------------------------------------------------------------
# [V20-PATCH] نصب قلاب‌ها روی کلاس Bot — یک‌بار، ایمن و برگشت‌پذیر
# ----------------------------------------------------------------
_V20_ORIG_SEND = None
_V20_ORIG_EDIT = None
_V20_PATCH_OK = False
try:
    import telegram as _v20_telegram

    _V20_ORIG_SEND = _v20_telegram.Bot.send_message
    _V20_ORIG_EDIT = _v20_telegram.Bot.edit_message_text
    if getattr(_v20_telegram.Bot.send_message, "__name__", "") != "v20_bot_send_message":
        _v20_telegram.Bot.send_message = v20_bot_send_message
        _v20_telegram.Bot.edit_message_text = v20_bot_edit_text
    _V20_PATCH_OK = (
        getattr(_v20_telegram.Bot.send_message, "__name__", "") == "v20_bot_send_message"
        and getattr(_v20_telegram.Bot.edit_message_text, "__name__", "") == "v20_bot_edit_text"
    )
except Exception as _v20_patch_exc:
    try:
        print(f"ApexRival V20 panel patch unavailable: {_v20_patch_exc!r}")
    except Exception:
        pass


# ----------------------------------------------------------------
# [V20-NAV] عملیات برگشت/خانه/بستن — همه با پیام محترمانه
# ----------------------------------------------------------------
async def v20_render_state(bot, chat_id: int, message_id: int, state: dict):
    """یک اسنپ‌شات را روی پیام پنل ادیت می‌کند (بدون قلاب، مستقیم)."""
    kw = {"chat_id": int(chat_id), "message_id": int(message_id), "text": str(state.get("text", "") or "")}
    pm = state.get("parse_mode", _V20_PM_UNSET)
    if pm is not _V20_PM_UNSET:
        kw["parse_mode"] = pm
    mk = state.get("markup")
    if mk is not None:
        try:
            nav = V20_NAV.get((int(chat_id), int(message_id)), {})
            depth = max(1, len(nav.get("stack", [])))
            mk = v20_decorate_markup(mk, depth=depth, is_home=bool(state.get("home")))
        except Exception:
            pass
        if mk is not None:
            kw["reply_markup"] = mk
    return await _V20_ORIG_EDIT(bot, **kw)


async def v20_nav_action(query, bot, action: str) -> None:
    """دکمه‌های V20|BK / V20|HM / V20|CL — قلب ناوبری."""
    msg = getattr(query, "message", None)
    if msg is None:
        await safe_answer_query(query, "این پنل دیگر فعال نیست ✨", True)
        return
    try:
        chat_id = int(getattr(msg, "chat_id", 0) or 0)
    except Exception:
        chat_id = 0
    if not chat_id:
        chat = getattr(msg, "chat", None)
        chat_id = int(getattr(chat, "id", 0) or 0)
    mid = int(getattr(msg, "message_id", 0) or 0)
    # id گروه‌ها منفی است؛ فقط صفر نامعتبر است
    if chat_id == 0 or mid <= 0:
        await safe_answer_query(query, "این پنل دیگر فعال نیست ✨", True)
        return
    key = (chat_id, mid)

    # ✖️ بستن: پنل واقعاً حذف می‌شود
    if action == "CL":
        v20_forget_panel(chat_id, mid)
        if bot is not None:
            try:
                await bot.delete_message(chat_id=chat_id, message_id=mid)
            except Exception:
                try:
                    await _V20_ORIG_EDIT(bot, chat_id=chat_id, message_id=mid,
                                         text="✅ پنل بسته شد.", reply_markup=None)
                except Exception:
                    pass
        await safe_answer_query(query, "پنل بسته شد ✅")
        return

    nav = V20_NAV.get(key)
    if not isinstance(nav, dict) or not nav.get("stack"):
        await safe_answer_query(query, "این پنل دیگر فعال نیست ✨", True)
        return
    stack = nav["stack"]

    # اگر الان روی «خانه» هستیم، برگشت یعنی بستن پنل
    if stack and stack[-1].get("home") and action == "BK":
        v20_forget_panel(chat_id, mid)
        if bot is not None:
            try:
                await bot.delete_message(chat_id=chat_id, message_id=mid)
            except Exception:
                pass
        await safe_answer_query(query, "پنل بسته شد ✅")
        return

    if action == "BK" and len(stack) > 1:
        stack.pop()
    else:
        home = v20_home_state(int(nav.get("owner") or chat_id))
        stack.append(home)
        if len(stack) > 16:
            del stack[: len(stack) - 16]

    try:
        await v20_render_state(bot, chat_id, mid, stack[-1])
    except Exception as exc:
        low = str(exc).lower()
        if "not modified" in low:
            await safe_answer_query(query, "همین صفحه در حال حاضر باز است.")
        else:
            await safe_answer_query(query, "برگشت موقتاً ممکن نیست؛ از دکمه‌های منو استفاده کن 🌿", True)
    try:
        nav["ts"] = v20_now()
    except Exception:
        pass


# ----------------------------------------------------------------
# [V20-CLOSE-INTERCEPT] دکمه‌ی ✕ بستنِ منوهای V5 → حالا پیام را
# واقعاً حذف می‌کند (قبلاً فقط متن «بسته شد» می‌ماند)
# ----------------------------------------------------------------
async def v20_close_intercept(update, context) -> None:
    try:
        query = getattr(update, "callback_query", None)
        if query is None:
            return
        try:
            await query.answer("بسته شد ✅")
        except Exception:
            pass
        msg = getattr(query, "message", None)
        bot = getattr(context, "bot", None)
        if msg is None:
            return
        try:
            chat_id = int(getattr(msg, "chat_id", 0) or 0)
        except Exception:
            chat_id = 0
        if not chat_id:
            chat = getattr(msg, "chat", None)
            chat_id = int(getattr(chat, "id", 0) or 0)
        mid = int(getattr(msg, "message_id", 0) or 0)
        # id گروه‌ها منفی است؛ فقط صفر نامعتبر است
        if chat_id == 0 or mid <= 0:
            return
        v20_forget_panel(chat_id, mid)
        deleted = False
        if bot is not None:
            try:
                await bot.delete_message(chat_id=chat_id, message_id=mid)
                deleted = True
            except Exception:
                deleted = False
        if not deleted:
            try:
                await safe_edit_query(query, "✅ بسته شد.", None)
            except Exception:
                pass
    except Exception as exc:
        try:
            audit("v20_close_intercept_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass
    finally:
        if _V20_AHS is not None:
            raise _V20_AHS


# ----------------------------------------------------------------
# [V20-PRUNE] پنل‌های کهنه: دکمه‌هایشان برداشته می‌شود تا دکمه‌ی مرده
# در چت نماند (ضد شلوغیِ بلندمدت)
# ----------------------------------------------------------------
async def v20_prune_panels() -> int:
    removed = 0
    try:
        now = v20_now()
        bot = V20_BOOT.get("bot")
        if bot is None:
            return 0
        for key in list(V20_NAV.keys()):
            nav = V20_NAV.get(key)
            if not isinstance(nav, dict):
                continue
            chat_id, mid = int(key[0]), int(key[1])
            try:
                hours = float(v20_gcfg(chat_id).get("stale_h", 12) or 12)
            except Exception:
                hours = 12.0
            try:
                enabled = bool(v20_gcfg(chat_id).get("stale", True))
            except Exception:
                enabled = True
            if not enabled:
                continue
            if now - float(nav.get("ts", 0) or 0) < hours * 3600.0:
                continue
            try:
                await bot.edit_message_reply_markup(
                    chat_id=chat_id, message_id=mid, reply_markup=None,
                )
            except Exception:
                pass
            v20_forget_panel(chat_id, mid)
            removed += 1
    except Exception:
        pass
    return removed


async def v20_prune_loop(app) -> None:
    while True:
        try:
            await asyncio.sleep(1200)
            await v20_prune_panels()
        except asyncio.CancelledError:
            return
        except Exception:
            try:
                await asyncio.sleep(120)
            except Exception:
                return

# ================================================================
# [V20-GROUP] بازی گروهیِ نسل بعد — تیم، چالش روزانه، قلب، غیبت، گزارش
# ================================================================

def v20_schedule(coro):
    """زمان‌بندی امن تسک — فقط وقتی لوپ در حال اجراست؛ وگرنه کوروتین
    بی‌صدا بسته می‌شود (ضد هشدارِ «never awaited» در سلف-چکِ import)."""
    try:
        loop = asyncio.get_running_loop()
    except Exception:
        try:
            coro.close()
        except Exception:
            pass
        return None
    try:
        return loop.create_task(coro)
    except Exception:
        try:
            coro.close()
        except Exception:
            pass
        return None

# ----------------------------------------------------------------
# [V20-TEAM] تیم‌های رقابتی — قرعه‌ی متعادل، امتیاز زنده، حس «ما vs آن‌ها»
# ----------------------------------------------------------------
def v20_team_entry(chat_id: int) -> dict:
    """تیم‌های همین گروه (اگر باشد) — {'red': [...], 'blue': [...], 'points': {...}}"""
    try:
        return v20_store()["teams"].get(group_key(int(chat_id)), {}) or {}
    except Exception:
        return {}


def v20_team_build(chat_id: int, players: list, game=None) -> dict:
    """قرعه‌ی متعادل بر اساس XP (مارپیچ) — قوی‌ها پخش می‌شوند."""
    try:
        uids = [int(u) for u in players if int(u or 0) > 0]
        uids = list(dict.fromkeys(uids))
        if len(uids) < 2:
            return v20_team_entry(chat_id)
        ranked = sorted(
            uids,
            key=lambda u: int(get_user(int(u)).get("xp", 0) or 0),
            reverse=True,
        )
        red: list = []
        blue: list = []
        for i, u in enumerate(ranked):
            if i % 4 in (0, 3):
                red.append(int(u))
            else:
                blue.append(int(u))
        entry = {
            "red": red,
            "blue": blue,
            "points": {"red": 0, "blue": 0},
            "ts": v20_now(),
        }
        v20_store()["teams"][group_key(int(chat_id))] = entry
        save_data(force=True)
        return entry
    except Exception:
        return v20_team_entry(chat_id)


def v20_team_name(team: str) -> str:
    return "🔴 تیم سرخ" if str(team) == "red" else "🔵 تیم آبی"


def v20_team_member_line(uid: int, game=None) -> str:
    try:
        name = name_of(int(uid), game) if game is not None else str(get_user(int(uid)).get("name") or "بازیکن")
    except Exception:
        name = "بازیکن"
    return f"{user_gender_icon(int(uid))} {mention_user(int(uid), str(name))}"


def v20_team_text(chat_id: int, game=None) -> str:
    entry = v20_team_entry(chat_id)
    if not entry:
        return (
            "⚔️ <b>تیم‌های رقابتی</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "هنوز تیمی ساخته نشده!\n"
            "🎮 اول با <code>/apex</code> بازی بساز، بعد <code>/apexteams</code> را بزن تا قرعه‌ی متعادل بین دو تیم انجام شود.\n"
            "🏆 هر XP که اعضای تیم بگیرند، امتیاز تیم می‌شود."
        )
    red = [int(x) for x in entry.get("red", [])]
    blue = [int(x) for x in entry.get("blue", [])]
    pr = int(entry.get("points", {}).get("red", 0) or 0)
    pb = int(entry.get("points", {}).get("blue", 0) or 0)
    lead = "🤝 تساوی کامل!"
    if pr > pb:
        lead = f"{v20_team_name('red')} جلوتر است ({pr - pb}+)"
    elif pb > pr:
        lead = f"{v20_team_name('blue')} جلوتر است ({pb - pr}+)"
    lines = [
        "⚔️ <b>تیم‌های رقابتی ApexRival</b>",
        "━━━━━━━━━━━━━━━━━━",
        f"🏆 وضعیت: <b>{escape(lead)}</b>",
        f"{v20_team_name('red')} — <b>{pr}</b> امتیاز",
    ]
    lines += ["   " + v20_team_member_line(u, game) for u in red] or ["   —"]
    lines.append(f"{v20_team_name('blue')} — <b>{pb}</b> امتیاز")
    lines += ["   " + v20_team_member_line(u, game) for u in blue] or ["   —"]
    lines += [
        "━━━━━━━━━━━━━━━━━━",
        "✨ هر XP اعضا = امتیاز تیم. تا آخر هفته بجنگید!",
    ]
    return "\n".join(lines)


def v20_team_markup() -> InlineKeyboardMarkup:
    return v5_markup([
        [v5_button("⚔️ قرعه‌ی مجدد", "V20|TM|NEW"), v5_button("↻ بروزرسانی", "V20|TM|R")],
    ])


def v20_team_credit(uid: int, amount: int) -> None:
    """XP هر کاربر به تیمش هم می‌رسد (سایه‌امتیاز؛ بازی دست نمی‌خورد).
    ملاحظه: add_xp مقدار «amount» را می‌دهد نه دلتای سطح — مثل دفتر هفتگی V19."""
    try:
        if int(amount) <= 0:
            return
        uid = int(uid)
        teams = v20_store()["teams"]
        if not teams:
            return
        for gk, entry in list(teams.items()):
            if not isinstance(entry, dict):
                continue
            for team in ("red", "blue"):
                if uid in [int(x) for x in entry.get(team, [])]:
                    pts = entry.setdefault("points", {})
                    pts[team] = int(pts.get(team, 0) or 0) + int(amount)
        save_data(force=True)
    except Exception:
        pass


async def v20_cmd_teams(update, context):
    """⚔️ /apexteams — ساخت/مشاهده‌ی تیم‌های رقابتی گروه."""
    try:
        user = getattr(update, "effective_user", None)
        msg = getattr(update, "message", None)
        if user is None or msg is None:
            return
        if is_banned(int(user.id)):
            await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
            return
        v17_touch_username(user)
        if not v7_chat_is_group(update):
            await msg.reply_text(
                "⚔️ <b>تیم‌ها مخصوص گروه‌اند!</b>\n━━━━━━━━━━━━━━━━━━\n"
                "این دستور را داخل <b>گروه</b> بزن: بازی فعال را به دو تیم متعادل تقسیم می‌کند.\n"
                "🎮 اول: <code>/apex</code> — بعد: <code>/apexteams</code>",
                parse_mode=ParseMode.HTML,
            )
            return
        chat_id = int(update.effective_chat.id)
        if not v20_gcfg(chat_id).get("teams", True):
            await msg.reply_text("⚙️ تیم‌های رقابتی توسط ادمین این گروه خاموش شده است.")
            return
        game = active_game(chat_id)
        entry = v20_team_entry(chat_id)
        players = []
        if game is not None:
            players = [int(x) for x in game.get("players", []) or []]
        if players and (not entry or len(entry.get("red", [])) + len(entry.get("blue", [])) != len(players)):
            entry = v20_team_build(chat_id, players, game)
        await msg.reply_text(
            v20_team_text(chat_id, game),
            parse_mode=ParseMode.HTML,
            reply_markup=v20_team_markup(),
        )
    except Exception as exc:
        try:
            audit("v20_cmd_teams_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass


async def v20_teams_action(update, context, parts):
    """دکمه‌های V20|TM| — قرعه مجدد و بروزرسانی."""
    try:
        query = getattr(update, "callback_query", None)
        if query is None:
            return
        chat = getattr(update, "effective_chat", None)
        chat_id = int(getattr(chat, "id", 0) or 0)
        if chat_id >= 0:
            await safe_answer_query(query, "⚔️ تیم‌ها مخصوص گروه‌هاست.", True)
            return
        game = active_game(chat_id)
        arg = parts[2] if len(parts) > 2 else "R"
        if arg == "NEW":
            players = [int(x) for x in (game.get("players", []) or [])] if game is not None else []
            if len(players) < 2:
                await safe_answer_query(query, "حداقل ۲ بازیکن لازم است 🎟", True)
                return
            v20_team_build(chat_id, players, game)
        await safe_edit_query(query, v20_team_text(chat_id, game), v20_team_markup())
    except Exception as exc:
        try:
            audit("v20_teams_action_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass


# ----------------------------------------------------------------
# [V20-DAILY] چالش روزانه‌ی گروه — هدف مشترک، جایزه‌ی جمعی
# ----------------------------------------------------------------
def v20_daily_entry(chat_id: int) -> dict:
    try:
        st = v20_store()["daily"]
        gk = group_key(int(chat_id))
        e = st.get(gk)
        today = v20_day_key()
        if not isinstance(e, dict) or e.get("date") != today:
            e = {"date": today, "turns": 0, "claimed": False, "players": {}}
            st[gk] = e
        return e
    except Exception:
        return {"date": v20_day_key(), "turns": 0, "claimed": False, "players": {}}


def v20_daily_tick(game: dict, questioner: int) -> None:
    """هر اعلام نوبت = یک قدمِ چالش روزانه (قلاب روی v7_turn_announcement)."""
    try:
        chat_id = int(game.get("chat_id") or 0)
        if chat_id >= 0:
            return
        if not v20_gcfg(chat_id).get("daily", True):
            return
        e = v20_daily_entry(chat_id)
        e["turns"] = int(e.get("turns", 0) or 0) + 1
        players = e.setdefault("players", {})
        k = user_key(int(questioner))
        players[k] = int(players.get(k, 0) or 0) + 1
        goal = int(v20_gcfg(chat_id).get("daily_goal", 25) or 25)
        if not e.get("claimed") and int(e["turns"]) >= goal:
            e["claimed"] = True
            v20_schedule(v20_daily_celebrate(chat_id, e))
        save_data(force=True)
    except Exception:
        pass


async def v20_daily_celebrate(chat_id: int, entry: dict) -> None:
    """جایزه‌ی جمعی چالش — با احترام به سکوت شب و ضد اذیت."""
    try:
        rewarded = 0
        for k in list(entry.get("players", {}).keys()):
            try:
                uid = int(str(k).replace("u", "") or 0)
            except Exception:
                continue
            if uid > 0:
                add_coins(uid, 8, "DailyChallenge")
                rewarded += 1
        text = (
            "🎯 <b>چالش روزانه کامل شد!</b>\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"🏆 این گروه امروز به هدف رسید؛ {rewarded} بازیکنِ فعال هرکدام <b>+۸ سکه</b> گرفتند 🪙\n"
            "📌 چالش فردا از اول صفر شروع می‌شود — قهرمانِ فردا کیست؟"
        )
        await v19_send_group(int(chat_id), text)
        save_data(force=True)
    except Exception as exc:
        try:
            audit("v20_daily_celebrate_error", 0, int(chat_id), repr(exc)[:200])
        except Exception:
            pass


def v20_daily_text(chat_id: int) -> str:
    e = v20_daily_entry(chat_id)
    goal = int(v20_gcfg(chat_id).get("daily_goal", 25) or 25)
    turns = int(e.get("turns", 0) or 0)
    active = len(e.get("players", {}))
    bar = v5_progress(min(turns, goal), max(goal, 1), 14)
    status = "✅ کامل شد — جایزه پرداخت گردید" if e.get("claimed") else "⏳ در جریان"
    left = max(0, goal - turns)
    return (
        "🎯 <b>چالش روزانه‌ی گروه</b>\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"📅 امروز: <b>{turns}</b> نوبت از <b>{goal}</b>\n"
        f"{bar}\n"
        f" وضعیت: <b>{status}</b>\n"
        f"👥 بازیکنان فعال امروز: <b>{active}</b>\n"
        + (f"🔥 فقط <b>{left}</b> نوبت تا جایزه‌ی جمعی مانده!\n" if left else "")
        + "━━━━━━━━━━━━━━━━━━\n"
        "🪙 جایزه: هر بازیکن فعال +۸ سکه — فقط با نوبت‌های <b>همین امروز</b>."
    )


def v20_daily_markup() -> InlineKeyboardMarkup:
    return v5_markup([
        [v5_button("↻ بروزرسانی", "V20|DL|R")],
    ])


