async def v20_cmd_heart(update, context):
    """❤️ /apexheart (ریپلای) — قلب محبت به بازیکن دیگر."""
    try:
        user = getattr(update, "effective_user", None)
        msg = getattr(update, "message", None)
        if user is None or msg is None:
            return
        if is_banned(int(user.id)):
            await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
            return
        target_msg = getattr(msg, "reply_to_message", None)
        target = getattr(target_msg, "from_user", None)
        if target is None:
            await msg.reply_text(
                "❤️ <b>قلب محبت</b>\n━━━━━━━━━━━━━━━━━━\n"
                "روی پیامِ کسی <b>ریپلای</b> کن و بعد <code>/apexheart</code> را بزن تا +۳ سکه هدیه بدهی 🪙\n"
                "🌹 روزی ۶ قلب برای هر نفر — محبت هم محدود شود تا ارزشمند بماند!",
                parse_mode=ParseMode.HTML,
            )
            return
        tuid = int(getattr(target, "id", 0) or 0)
        if tuid <= 0 or getattr(target, "is_bot", False):
            await msg.reply_text("🤖 به ربات‌ها قلب نمی‌دهیم؛ به آدم‌ها! 😄")
            return
        if tuid == int(user.id):
            await msg.reply_text("💖 خودسازی هم خوبه، ولی قلب را به بقیه بده! روی پیام دیگری ریپلای کن.")
            return
        day = v20_day_key()
        hearts = v20_store()["hearts"]
        day_map = hearts.setdefault(day, {})
        used = int(day_map.get(user_key(int(user.id)), 0) or 0)
        if used >= V20_HEART_DAILY_LIMIT:
            await msg.reply_text("🌹 سهمیه‌ی قلبت برای امروز تمام شد؛ فردا با انرژی تازه!")
            return
        day_map[user_key(int(user.id))] = used + 1
        add_coins(tuid, V20_HEART_COINS, "HeartGift")
        save_data(force=True)
        giver_name = str(get_user(int(user.id), getattr(user, "first_name", None) or "بازیکن").get("name") or "بازیکن")
        target_name = str(get_user(tuid, getattr(target, "first_name", None) or "بازیکن").get("name") or "بازیکن")
        await msg.reply_text(
            "❤️ <b>قلب محبت</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"{user_gender_icon(int(user.id))} {mention_user(int(user.id), giver_name)} "
            f"یک قلب به {user_gender_icon(tuid)} {mention_user(tuid, target_name)} داد 🌹\n"
            f"🪙 <b>+{V20_HEART_COINS} سکه</b> هدیه شد!\n"
            f"🎁 امروز شما {used + 1} از {V20_HEART_DAILY_LIMIT} قلب را داده‌اید.",
            parse_mode=ParseMode.HTML,
        )
    except Exception as exc:
        try:
            audit("v20_cmd_heart_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass


# ----------------------------------------------------------------
# [V20-BRB] موقتاً نیستم — وقتی نیستی، اسمت «🌙» می‌شود
# ----------------------------------------------------------------
V20_BRB_HOURS = 6


def v20_is_brb(uid: int) -> bool:
    try:
        st = v20_store()["brb"]
        k = user_key(int(uid))
        ts = st.get(k)
        if ts is None:
            return False
        if v20_now() - float(ts or 0) > V20_BRB_HOURS * 3600.0:
            st.pop(k, None)
            return False
        return True
    except Exception:
        return False


async def v20_cmd_brb(update, context):
    """🌙 /apexbrb — «موقتاً نیستم»."""
    try:
        user = getattr(update, "effective_user", None)
        msg = getattr(update, "message", None)
        if user is None or msg is None:
            return
        if is_banned(int(user.id)):
            await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
            return
        v20_store()["brb"][user_key(int(user.id))] = v20_now()
        save_data(force=True)
        await msg.reply_text(
            "🌙 <b>حالت «موقتاً نیستم» روشن شد!</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"{user_gender_icon(int(user.id))} {v19_mention(int(user.id))} کنار اسمت یک ماه 🌙 دیده می‌شود تا بقیه بدانند پاسخ نمی‌دهی.\n"
            f"⏳ بعد از {V20_BRB_HOURS} ساعت خودکار برمی‌گردد — یا همین حالا با <code>/apexback</code>.",
            parse_mode=ParseMode.HTML,
        )
    except Exception as exc:
        try:
            audit("v20_cmd_brb_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass


async def v20_cmd_back(update, context):
    """🌞 /apexback — برگشتن از حالت غیبت."""
    try:
        user = getattr(update, "effective_user", None)
        msg = getattr(update, "message", None)
        if user is None or msg is None:
            return
        if is_banned(int(user.id)):
            await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
            return
        v20_store()["brb"].pop(user_key(int(user.id)), None)
        save_data(force=True)
        await msg.reply_text(
            "🌞 <b>خوش برگشتی!</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"{user_gender_icon(int(user.id))} {v19_mention(int(user.id))} ماه کنار اسمت برداشته شد — دوباره تگ می‌شوی 🎯",
            parse_mode=ParseMode.HTML,
        )
    except Exception as exc:
        try:
            audit("v20_cmd_back_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass


# ----------------------------------------------------------------
# [V20-RECAP] گزارش هفتگی گروه + جشن دهمین بازی
# ----------------------------------------------------------------
def v20_gstats_entry(chat_id: int) -> dict:
    try:
        st = v20_store()["gstats"]
        gk = group_key(int(chat_id))
        e = st.get(gk)
        wk = v19_week_key()
        if not isinstance(e, dict) or e.get("week") != wk:
            e = {"week": wk, "games": 0, "turns": 0, "milestone": 0, "ts": v20_now()}
            st[gk] = e
        return e
    except Exception:
        return {"week": "", "games": 0, "turns": 0, "milestone": 0, "ts": 0}


def v20_game_ended(game: dict) -> None:
    """قلاب پایان بازی: آمار هفتگی گروه + جشن هر ۱۰ بازی (سایه‌ای، بدون دست‌کاری)."""
    try:
        chat_id = int(game.get("chat_id") or 0)
        if chat_id >= 0:
            return
        e = v20_gstats_entry(chat_id)
        e["games"] = int(e.get("games", 0) or 0) + 1
        e["ts"] = v20_now()
        games = int(e["games"])
        if games > 0 and games % 10 == 0:
            e["milestone"] = games
            v20_schedule(v20_milestone_msg(chat_id, games))
        save_data(force=True)
    except Exception:
        pass


async def v20_milestone_msg(chat_id: int, games: int) -> None:
    try:
        text = (
            "🎉 <b>رکورد گروه!</b>\n━━━━━━━━━━━━━━━━━━\n"
            f"این گروه دقیقاً <b>{games} بازی</b> با ApexRival تجربه کرد 🏆\n"
            "این یعنی ساعت‌ها خنده، جرئت و رقابت. تشکر از همه‌ی قهرمان‌ها 🤝"
        )
        await v19_send_group(int(chat_id), text)
    except Exception:
        pass


def v20_recap_text(chat_id: int) -> str:
    e = v20_gstats_entry(chat_id)
    games = int(e.get("games", 0) or 0)
    lines = [
        "📊 <b>گزارش هفتگی گروه</b>",
        "━━━━━━━━━━━━━━━━━━",
        f"🎮 بازی‌های این هفته: <b>{games}</b>",
        f"⚔️ آخرین جشن رکورد: <b>{int(e.get('milestone', 0) or 0) or '—'}</b> بازی",
        "━━━━━━━━━━━━━━━━━━",
        "🌍 <b>سه قهرمانِ برترِ این هفته (کل ربات):</b>",
    ]
    try:
        top = v19_week_top(3)
        medals = ["🥇", "🥈", "🥉"]
        if top:
            for i, (xp, uid, name) in enumerate(top):
                lines.append(f"{medals[i] if i < 3 else '▫️'} {mention_user(int(uid), str(name))} · ⭐ {int(xp):,}")
        else:
            lines.append("— این هفته هنوز کسی XP نگرفته؛ اولین قهرمان باش!")
    except Exception:
        lines.append("—")
    lines += [
        "━━━━━━━━━━━━━━━━━━",
        "📅 دفتر هفته هر دوشنبه صفر می‌شود — همیشه شانسی داری!",
    ]
    return "\n".join(lines)


async def v20_cmd_recap(update, context):
    """📊 /apexrecap — گزارش هفتگی گروه."""
    try:
        user = getattr(update, "effective_user", None)
        msg = getattr(update, "message", None)
        if user is None or msg is None:
            return
        if is_banned(int(user.id)):
            await msg.reply_text("🚫 دسترسی شما به ApexRival مسدود شده است.")
            return
        v17_touch_username(user)
        if not v7_chat_is_group(update):
            await msg.reply_text(
                "📊 <b>گزارش هفتگی مخصوص گروه‌است!</b>\n━━━━━━━━━━━━━━━━━━\n"
                "داخل گروه بزن تا بازی‌های هفته‌ی جمع‌تان را ببینی.",
                parse_mode=ParseMode.HTML,
            )
            return
        chat_id = int(update.effective_chat.id)
        await msg.reply_text(v20_recap_text(chat_id), parse_mode=ParseMode.HTML)
    except Exception as exc:
        try:
            audit("v20_cmd_recap_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass

