# ۱) XP → امتیاز تیم (سایه‌امتیاز؛ روی خودِ XP اثری ندارد)
_AR20_OLD_ADD_XP = add_xp


def add_xp(uid: int, amount: int, name: str = "کاربر", group_mult: int = 1) -> int:
    delta = _AR20_OLD_ADD_XP(uid, amount, name, group_mult)
    try:
        if int(amount) > 0:
            v20_team_credit(int(uid), int(amount))
    except Exception:
        pass
    return delta


# ۲) اعلام نوبت → شمارش چالش روزانه‌ی گروه
_AR20_OLD_TURN = v7_turn_announcement


def v7_turn_announcement(game: dict[str, Any], questioner: int) -> str:
    text = _AR20_OLD_TURN(game, int(questioner))
    try:
        v20_daily_tick(game, int(questioner))
    except Exception:
        pass
    return text


# ۳) پایان بازی → آمار هفتگی گروه + جشن رکورد
_AR20_OLD_ENDGAME = end_game


def end_game(game: dict[str, Any], reason: str = "") -> Any:
    try:
        if isinstance(game, dict):
            v20_game_ended(game)
    except Exception:
        pass
    return _AR20_OLD_ENDGAME(game, reason)


# ۴) منشن → نشانِ «موقتاً نیستم» 🌙
_AR20_OLD_MENTION = mention_user


def mention_user(uid: int, name: str) -> str:
    s = _AR20_OLD_MENTION(uid, name)
    try:
        if v20_is_brb(int(uid)):
            return str(s) + " 🌙"
    except Exception:
        pass
    return s


