_AR20_OLD_SET_TEXT = v19_set_text


def v19_set_text(chat_id: int) -> str:
    base = _AR20_OLD_SET_TEXT(chat_id)
    try:
        g = v20_gcfg(int(chat_id))
        base += (
            "\n━━━━━━━━━━━━━━━━━━\n"
            "🧹 <b>پنل هوشمند V20</b>\n"
            f"⬅️ دکمه‌ی برگشت/بستن منوها: <b>{'✅ فعال' if g['back'] else '❌ خاموش'}</b>\n"
            f"🗑 حذف پیام دستور (مثل /start): <b>{'✅ فعال' if g['delcmd'] else '❌ خاموش'}</b>\n"
            f"🧊 منقضی‌شدن پنل‌های کهنه: <b>{'✅ ' + str(g['stale_h']) + ' ساعت' if g['stale'] else '❌ خاموش'}</b>\n"
            f"⚔️ تیم‌های رقابتی: <b>{'✅ فعال' if g['teams'] else '❌ خاموش'}</b>\n"
            f"🎯 چالش روزانه (هدف {g['daily_goal']} نوبت): <b>{'✅ فعال' if g['daily'] else '❌ خاموش'}</b>"
        )
    except Exception:
        pass
    return base


_AR20_OLD_SET_MARKUP = v19_set_markup


def v19_set_markup(chat_id: int):
    mk = _AR20_OLD_SET_MARKUP(chat_id)
    try:
        g = v20_gcfg(int(chat_id))
        rows = [list(r) for r in (getattr(mk, "inline_keyboard", []) or [])]
        rows += [
            [v5_button("⬅️ برگشت منوها: " + ("✅" if g["back"] else "❌"), "V20|SET|BK")],
            [v5_button("🗑 حذف دستور: " + ("✅" if g["delcmd"] else "❌"), "V20|SET|DC")],
            [v5_button("🧖 منقضی‌شدن پنل: " + ("✅" if g["stale"] else "❌"), "V20|SET|DU")],
            [v5_button("−", "V20|SET|GM"), v5_button(f"🎯 هدف روزانه: {g['daily_goal']}", "V20|SET|NOP"), v5_button("＋", "V20|SET|GP")],
            [v5_button("🎯 چالش روزانه: " + ("✅" if g["daily"] else "❌"), "V20|SET|DL")],
            [v5_button("⚔️ تیم‌ها: " + ("✅" if g["teams"] else "❌"), "V20|SET|TM")],
        ]
        return v5_markup(rows)
    except Exception:
        return mk


