# [V20-CALLBACK] روتر دکمه‌های V20| — همه با try/except زره‌پوش
# ----------------------------------------------------------------
async def v20_set_action(update, context, parts) -> None:
    """دکمه‌های تنظیمات V20 — فقط ادمین‌ها."""
    try:
        query = getattr(update, "callback_query", None)
        if query is None:
            return
        chat = getattr(update, "effective_chat", None)
        chat_id = int(getattr(chat, "id", 0) or 0)
        arg = parts[2] if len(parts) > 2 else ""
        if arg == "NOP":
            await safe_answer_query(query)
            return
        if not await v19_is_chat_admin(update, context):
            await safe_answer_query(query, "👑 فقط ادمین‌های گروه می‌توانند تنظیمات را عوض کنند.", True)
            return
        cfg = v20_gcfg(chat_id)
        if arg == "BK":
            cfg["back"] = not bool(cfg.get("back", True))
        elif arg == "DC":
            cfg["delcmd"] = not bool(cfg.get("delcmd", True))
        elif arg == "DU":
            cfg["stale"] = not bool(cfg.get("stale", True))
        elif arg == "DL":
            cfg["daily"] = not bool(cfg.get("daily", True))
        elif arg == "TM":
            cfg["teams"] = not bool(cfg.get("teams", True))
        elif arg == "GP":
            cfg["daily_goal"] = min(500, int(cfg.get("daily_goal", 25)) + 5)
        elif arg == "GM":
            cfg["daily_goal"] = max(5, int(cfg.get("daily_goal", 25)) - 5)
        v20_save_cfg(chat_id, cfg)
        await safe_edit_query(query, v19_set_text(chat_id), v19_set_markup(chat_id))
    except Exception as exc:
        try:
            audit("v20_set_action_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass


async def v20_callback_router(update, context):
    """مرکز dispatch دکمه‌های V20 — الگوی داده همیشه کوتاه (≤ ۶۴ بایت)."""
    try:
        query = getattr(update, "callback_query", None)
        if query is None:
            return
        data = str(getattr(query, "data", "") or "")
        if not data.startswith("V20|"):
            return
        try:
            await query.answer()
        except Exception:
            pass
        parts = data.split("|")
        action = parts[1] if len(parts) > 1 else ""
        if action in ("BK", "HM", "CL"):
            bot = getattr(context, "bot", None)
            await v20_nav_action(query, bot, action)
        elif action == "SET":
            await v20_set_action(update, context, parts)
        elif action == "TM":
            await v20_teams_action(update, context, parts)
        elif action == "DL":
            await v20_daily_action(update, context, parts)
    except Exception as exc:
        try:
            audit("v20_router_error", 0, 0, repr(exc)[:200])
        except Exception:
            pass
    finally:
        if _V20_AHS is not None:
            raise _V20_AHS


# ----------------------------------------------------------------
# [V20-REGISTER] ثبت هندلرهای V20 روی اپلیکیشن اصلی
# ----------------------------------------------------------------
def v20_register_handlers(app) -> None:
    try:
        V20_BOOT["app"] = app
        try:
            V20_BOOT["bot"] = app.bot
        except Exception:
            pass
        # شنود منو — قبل از همه (گروه -۹۹؛ بعد از بک‌گراند AR14، قبل از گیت‌های V19)
        try:
            if _V20_TypeHandler is not None:
                app.add_handler(_V20_TypeHandler(Update, v20_menu_sniffer), group=-99)
        except Exception:
            pass
        # روتر V20| و بستنِ واقعی V5|CLOSE — قبل از زنجیره‌های اصلی (گروه -۹۶)
        try:
            app.add_handler(CallbackQueryHandler(v20_callback_router, pattern=r"^V20\|"), group=-96)
        except Exception:
            pass
        try:
            app.add_handler(CallbackQueryHandler(v20_close_intercept, pattern=r"^V5\|CLOSE$"), group=-96)
        except Exception:
            pass
        # دستورات جدید
        for name, fn in (
            ("apexteams", v20_cmd_teams),
            ("apexdaily", v20_cmd_daily),
            ("apexheart", v20_cmd_heart),
            ("apexbrb", v20_cmd_brb),
            ("apexback", v20_cmd_back),
            ("apexrecap", v20_cmd_recap),
        ):
            try:
                app.add_handler(CommandHandler(name, fn))
            except Exception:
                pass
    except Exception as exc:
        try:
            print(f"ApexRival V20 register warning: {exc!r}")
        except Exception:
            pass


_AR20_OLD_REGISTER = ar15_register_handlers


def ar15_register_handlers(app):
    _AR20_OLD_REGISTER(app)
    v20_register_handlers(app)


# ----------------------------------------------------------------
# [V20-BOOT] post_init: بوت پنل‌ها + حلقه‌ی منقضی‌سازی
# ----------------------------------------------------------------
async def v20_boot(application) -> None:
    try:
        V20_BOOT["app"] = application
        try:
            V20_BOOT["bot"] = application.bot
        except Exception:
            pass
        V20_BOOT["boot_ts"] = now_ts()
        try:
            V20_BOOT["prune_task"] = application.create_task(v20_prune_loop(application))
        except Exception:
            V20_BOOT["prune_task"] = None
        print(
            "ApexRival V20 MEGA UX layer online | panel-manager=on | "
            "back-nav=on | close-deletes=on | stale-prune=on | teams=on | "
            "daily-challenge=on | hearts=on | brb=on | recap=on"
        )
    except Exception as exc:
        try:
            print(f"ApexRival V20 boot warning: {exc!r}")
        except Exception:
            pass


_AR20_OLD_POST_INIT = ar15_post_init


async def ar15_post_init(application):
    await _AR20_OLD_POST_INIT(application)
    await v20_boot(application)


# ----------------------------------------------------------------
# [V20-CHECK] سلف-چک لایه — هنگام لود اجرا می‌شود
# ----------------------------------------------------------------
async def v20_self_check_async() -> bool:
    """شبیه‌سازی کامل چرخه‌ی پنل — بدون شبکه، با باتِ جعلی.
    دقیقاً همان سناریوی گزارش‌شده: /start دوبار پشت سر هم."""
    global _V20_ORIG_SEND, _V20_ORIG_EDIT
    saved_send, saved_edit = _V20_ORIG_SEND, _V20_ORIG_EDIT
    sent: list = []
    deleted: list = []
    edited: list = []
    cmd_deleted: list = []

    class _FB:  # باتِ جعلی
        async def send_message(self, *a, **kw):
            sent.append((kw.get("chat_id"), kw.get("text"), kw.get("reply_markup")))
            class _M:
                message_id = 500 + len(sent)
            return _M()

        async def delete_message(self, chat_id=None, message_id=None, **kw):
            deleted.append((chat_id, message_id))
            return True

        async def edit_message_text(self, *a, **kw):
            edited.append((kw.get("chat_id"), kw.get("message_id"), kw.get("text")))
            return True

    class _FU:
        def __init__(self, uid):
            self.id = uid
            self.first_name = "Probe"
            self.is_bot = False

    class _FC:
        def __init__(self, cid, ctype):
            self.id = cid
            self.type = ctype

    class _FM:
        def __init__(self, mid, chat, text=""):
            self.message_id = mid
            self.chat_id = chat.id
            self.chat = chat
            self.text = text

    class _FQ:
        def __init__(self, uid, data, chat, mid):
            self.from_user = _FU(uid)
            self.data = data
            self.message = _FM(mid, chat)
            self.answers = []

        async def answer(self, text=None, show_alert=False):
            self.answers.append(text)
            return True

    class _FUd:
        def __init__(self, chat, user, message=None, query=None):
            self.effective_chat = chat
            self.effective_user = user
            self.message = message
            self.callback_query = query

    class _FX:
        def __init__(self, bot):
            self.bot = bot

    bot = _FB()

    async def _fake_orig_send(self, *a, **kw):
        return await bot.send_message(*a, **kw)

    async def _fake_orig_edit(self, *a, **kw):
        return await bot.edit_message_text(*a, **kw)

    ok = True
    try:
        _V20_ORIG_SEND = _fake_orig_send
        _V20_ORIG_EDIT = _fake_orig_edit
        probe_uid = 123456700
        probe_chat = 123456700  # خصوصی: id چت = id کاربر

        # --- ۱) اولین /start: پنل باز می‌شود + پیام دستور پاک می‌شود
        upd1 = _FUd(_FC(probe_chat, "private"), _FU(probe_uid), message=_FM(901, _FC(probe_chat, "private"), "/start"))
        await v20_menu_sniffer(upd1, _FX(bot))
        assert (probe_chat, 901) in deleted, f"command message not cleaned: {deleted}"
        mk = v5_markup([[v5_button("🎮 تست", "V5|HOME")]])
        await v20_bot_send_message(bot, chat_id=probe_chat, text="پنل اول", reply_markup=mk)
        assert len(sent) == 1, f"send1 failed: {len(sent)}"
        mid1 = 500 + 1
        assert V20_PANELS.get((probe_chat, probe_uid)) == [mid1], "panel1 not tracked"
        assert (probe_chat, mid1) in V20_NAV, "nav1 missing"
        # دکمه‌ی بستن به کیبورد اضافه شده باشد
        row_texts = [str(b.text) for b in sent[0][2].inline_keyboard[-1]]
        assert any("بستن" in t for t in row_texts), f"close button missing: {row_texts}"

        # --- ۲) دومین /start: پنل قبلی باید بسته و حذف شود (قلب رفع باگ)
        upd2 = _FUd(_FC(probe_chat, "private"), _FU(probe_uid), message=_FM(902, _FC(probe_chat, "private"), "/start"))
        await v20_menu_sniffer(upd2, _FX(bot))
        await v20_bot_send_message(bot, chat_id=probe_chat, text="پنل دوم", reply_markup=mk)
        assert len(sent) == 2, f"send2 failed: {len(sent)}"
        mid2 = 500 + 2
        assert (probe_chat, mid1) in deleted, f"OLD PANEL NOT DELETED: {deleted}"
        assert (probe_chat, mid1) not in V20_NAV, "nav1 still alive"
        assert V20_PANELS.get((probe_chat, probe_uid)) == [mid2], "panel2 not tracked"

        # --- ۳) ناوبری: ادیت صفحه دوم + برگشت
        await v20_bot_edit_text(bot, chat_id=probe_chat, message_id=mid2,
                                text="صفحه دوم", reply_markup=mk)
        assert len(edited) == 1 and len(V20_NAV[(probe_chat, mid2)]["stack"]) == 2, "edit push failed"
        q_back = _FQ(probe_uid, "V20|BK", _FC(probe_chat, "private"), mid2)
        await v20_nav_action(q_back, bot, "BK")
        assert len(edited) == 2 and edited[1][2] == "پنل دوم", f"back render failed: {edited}"
        assert len(V20_NAV[(probe_chat, mid2)]["stack"]) == 1

        # --- ۴) بستن: پنل واقعاً حذف می‌شود
        q_close = _FQ(probe_uid, "V20|CL", _FC(probe_chat, "private"), mid2)
        await v20_nav_action(q_close, bot, "CL")
        assert (probe_chat, mid2) in deleted, "close did not delete"
        assert (probe_chat, mid2) not in V20_NAV, "close did not forget panel"

        # --- ۵) گروه: دستورِ غیرمنویی نباید پنل ردیابی کند (جریان بازی سالم)
        # (در تولیدِ واقعی هر آپدیت تسکِ خودش را دارد؛ اینجا کانتکست را شبیهِ
        # تسکِ تازه صفر می‌کنیم)
        v20_ctx_set(None)
        gchat = -100123456700
        V20_PANELS.setdefault((gchat, probe_uid), []).append(777)
        V20_NAV[(gchat, 777)] = {"owner": probe_uid, "stack": [{"text": "g", "parse_mode": _V20_PM_UNSET, "markup": mk, "home": False, "ts": v20_now()}], "ts": v20_now()}
        upd3 = _FUd(_FC(gchat, "supergroup"), _FU(probe_uid), message=_FM(903, _FC(gchat, "supergroup"), "جواب نوبت"))
        await v20_menu_sniffer(upd3, _FX(bot))
        ctx_now = v20_ctx_get()
        assert ctx_now is None or not ctx_now.get("menu"), "game text must not set menu ctx"
        await v20_bot_send_message(bot, chat_id=gchat, text="اعلان نوبت", reply_markup=mk)
        assert (gchat, 777) not in deleted, "game flow wrongly deduped!"
        assert (gchat, 500 + len(sent)) not in V20_NAV, "game send wrongly tracked"
        # گروه + دستور منویی → پنل قبلی همان کاربر حذف می‌شود
        upd4 = _FUd(_FC(gchat, "supergroup"), _FU(probe_uid), message=_FM(904, _FC(gchat, "supergroup"), "/apexprofile"))
        await v20_menu_sniffer(upd4, _FX(bot))
        await v20_bot_send_message(bot, chat_id=gchat, text="پروفایل", reply_markup=mk)
        assert (gchat, 777) in deleted, "group menu dedupe failed"
    except Exception as exc:
        try:
            print(f"ApexRival V20 async self-check FAILED: {exc!r}")
        except Exception:
            pass
        ok = False
    finally:
        _V20_ORIG_SEND = saved_send
        _V20_ORIG_EDIT = saved_edit
        # پاک‌سازی کامل ردپای پروب
        try:
            V20_PANELS.pop((123456700, 123456700), None)
            V20_PANELS.pop((-100123456700, 123456700), None)
            for mid in (501, 502, 503, 504, 505, 506):
                V20_NAV.pop((123456700, mid), None)
                V20_NAV.pop((-100123456700, mid), None)
            V20_NAV.pop((-100123456700, 777), None)
            V20_PENDING.pop((123456700, 123456700), None)
            V20_PENDING.pop((-100123456700, 123456700), None)
        except Exception:
            pass
    return ok


def v20_sanitize_probes() -> None:
    """پاک‌سازی پروب‌های ساختگیِ سلف‌چک‌ها از مخزن پایدار — ضد آجرِ ری‌استارت.
    (سلف‌چک V19 پروبِ g-100999 را ذخیره می‌کند ولی پاپِ حافظه بدون ذخیره
    می‌ماند؛ این تابع هر دو لایه را تمیز و ذخیره می‌کند.)"""
    try:
        changed = False
        try:
            v19cfg = DATA.get("v19", {}).get("cfg", {})
            if isinstance(v19cfg, dict):
                gk = group_key(-100999)
                if gk in v19cfg:
                    v19cfg.pop(gk, None)
                    changed = True
        except Exception:
            pass
        try:
            v20s = DATA.get("v20", {})
            if isinstance(v20s, dict):
                for section in ("gcfg", "teams", "daily", "gstats"):
                    m = v20s.get(section)
                    if isinstance(m, dict):
                        for pid in (-100770, -100771, -100772, -100773, -100774, -100999):
                            gk = group_key(pid)
                            if gk in m:
                                m.pop(gk, None)
                                changed = True
        except Exception:
            pass
        if changed:
            save_data(force=True)
    except Exception:
        pass


def v20_self_check() -> None:
    # ۰) پروب‌های ساختگیِ اجرای قبلی تمیز شوند (idempotency کامل)
    v20_sanitize_probes()
    # ۱) همه‌ی توابع کلیدی تعریف شده‌اند
    for fn in (
        v20_store, v20_gcfg, v20_save_cfg, v20_ctx_get, v20_ctx_set,
        v20_decorate_markup, v20_home_state, v20_prune_pending,
        v20_forget_panel, v20_menu_sniffer, v20_after_send,
        v20_bot_send_message, v20_bot_edit_text, v20_render_state,
        v20_nav_action, v20_close_intercept, v20_prune_panels, v20_prune_loop,
        v20_team_entry, v20_team_build, v20_team_credit, v20_team_text,
        v20_team_markup, v20_cmd_teams, v20_teams_action,
        v20_daily_entry, v20_daily_tick, v20_daily_text, v20_daily_markup,
        v20_daily_celebrate, v20_cmd_daily, v20_daily_action,
        v20_hearts_today, v20_cmd_heart, v20_is_brb, v20_cmd_brb, v20_cmd_back,
        v20_gstats_entry, v20_game_ended, v20_milestone_msg, v20_recap_text,
        v20_cmd_recap, v20_expand_banks, v20_set_action, v20_callback_router,
        v20_register_handlers, v20_boot, v20_self_check_async,
        v20_sanitize_probes, v20_schedule,
    ):
        assert callable(fn), f"v20 missing function: {getattr(fn, '__name__', fn)}"
    # ۲) منطق تزئین: منوی بی‌ناوبری ← ردیف اضافه؛ منوی دارای ناوبری ← دست‌نخورده
    plain = v5_markup([[v5_button("🎮 تست", "V5|HOME")], [v5_button("🏆 رنک", "V5|RANK")]])
    dec = v20_decorate_markup(plain, depth=1, is_home=False)
    assert isinstance(dec, InlineKeyboardMarkup) and len(dec.inline_keyboard) == 3, "decorate depth1"
    last_texts = [str(b.text) for b in dec.inline_keyboard[-1]]
    assert any("منوی اصلی" in t for t in last_texts) and any("بستن" in t for t in last_texts), last_texts
    dec_home = v20_decorate_markup(plain, depth=1, is_home=True)
    assert len(dec_home.inline_keyboard) == 3 and any("بستن پنل" in str(b.text) for b in dec_home.inline_keyboard[-1]), "decorate home"
    dec_deep = v20_decorate_markup(plain, depth=3, is_home=False)
    assert any("بازگشت" in str(b.text) for b in dec_deep.inline_keyboard[-1]), "decorate deep"
    navvy = v5_markup([[v5_button("⌂ خانه", "V5|HOME")], [v5_button("✕ بستن", "V5|CLOSE")]])
    assert v20_decorate_markup(navvy, depth=1, is_home=False) is navvy, "navvy must stay"
    assert v20_decorate_markup(None, depth=2, is_home=False) is None, "none stays"
    # ۳) خانه‌ی ناوبری از رندرهای واقعی ساخته می‌شود
    _h = v20_home_state(123456789)
    assert isinstance(_h["markup"], InlineKeyboardMarkup) and _h["home"] is True
    assert "ApexRival" in str(_h["text"])
    # ۴) تنظیمات: پیش‌فرض‌ها + تغییر + ماندگاری + پاک‌سازی
    probe_gid = -100770
    cfg = v20_gcfg(probe_gid)
    assert cfg["back"] is True and cfg["delcmd"] is True and cfg["teams"] is True
    assert 5 <= cfg["daily_goal"] <= 500 and 1 <= cfg["pmax"] <= 12
    cfg2 = dict(cfg)
    cfg2["back"] = False
    cfg2["daily_goal"] = 40
    v20_save_cfg(probe_gid, cfg2)
    assert v20_gcfg(probe_gid)["back"] is False and v20_gcfg(probe_gid)["daily_goal"] == 40
    try:
        v20_store()["gcfg"].pop(group_key(probe_gid), None)
    except Exception:
        pass
    # ۵) دستورات جدید در گیت و منو
    for cmd in ("apexteams", "apexdaily", "apexheart", "apexbrb", "apexback", "apexrecap"):
        assert cmd in V17_UNIQUE_COMMANDS, f"gate missing: {cmd}"
        assert 1 <= len(cmd) <= 32 and cmd.isascii() and cmd.islower(), cmd
    menu_names = [str(c.command) for c in V17_COMMAND_MENU]
    for cmd in ("apexteams", "apexdaily", "apexrecap", "apexheart", "apexbrb", "apexback", "apex", "start"):
        assert cmd in menu_names, f"menu missing: {cmd}"
    assert menu_names[0] == "apex"
    # ۶) پنل تنظیمات V19 حالا بخش V20 دارد
    txt = v19_set_text(-100771)
    assert "پنل هوشمند V20" in txt, "set text v20 section missing"
    mk = v19_set_markup(-100771)
    flat = [str(b.callback_data or "") for row in mk.inline_keyboard for b in row]
    assert any(d.startswith("V20|SET|") for d in flat), "set markup v20 rows missing"
    # ۷) الگوی callbackها کوتاه و معتبر (≤ ۶۴ بایت)
    for sample in (
        "V20|BK", "V20|HM", "V20|CL", "V20|TM|NEW", "V20|TM|R", "V20|DL|R",
        "V20|SET|BK", "V20|SET|DC", "V20|SET|DU", "V20|SET|DL", "V20|SET|TM",
        "V20|SET|GP", "V20|SET|GM", "V20|SET|NOP",
    ):
        assert 1 <= len(sample.encode("utf-8")) <= 64, sample
        assert sample.startswith("V20|"), sample
    # ۸) بانک‌ها واقعاً بزرگ‌تر شده‌اند
    assert isinstance(_V20_EXPAND_REPORT, dict) and len(_V20_EXPAND_REPORT) >= 16
    total_new = sum(_V20_EXPAND_REPORT.values())
    assert total_new >= 120, f"v20 bank expansion too small: {total_new}"
    sample_v20 = V20_BANK_ADDITIONS["truth"][0]
    assert sample_v20 in V18_FACTORY.get("truth", []), "factory not synced"
    for key in ("truth", "dare", "secret", "drama", "flirty", "scenario", "mind",
                "wouldyou", "memory", "relation", "cringe", "adult", "dream",
                "regret", "future", "penalty"):
        bank = V18_FACTORY.get(key, [])
        assert len(bank) == len(set(str(x) for x in bank)), f"v20 factory duplicates: {key}"
    # ۹) قلاب‌ها واقعاً نصب شده‌اند
    assert callable(_AR20_OLD_ADD_XP) and add_xp.__name__ == "add_xp"
    assert callable(_AR20_OLD_TURN) and v7_turn_announcement.__name__ == "v7_turn_announcement"
    assert callable(_AR20_OLD_ENDGAME) and callable(_AR20_OLD_MENTION)
    assert callable(_AR20_OLD_REGISTER) and callable(_AR20_OLD_POST_INIT)
    assert callable(_AR20_OLD_SET_TEXT) and callable(_AR20_OLD_SET_MARKUP)
    # ۱۰) منشن + برب
    probe_uid = 987654321
    v20_store()["brb"][user_key(probe_uid)] = v20_now()
    assert v20_is_brb(probe_uid) is True
    m = mention_user(probe_uid, "ProbeMoon")
    assert str(m).endswith("🌙"), m
    v20_store()["brb"].pop(user_key(probe_uid), None)
    assert v20_is_brb(probe_uid) is False
    # ۱۱) تیم‌ها: قرعه‌ی متعادل + امتیاز سایه‌ای
    _t_probe = -100772
    _t_users = [123456701, 123456702, 123456703, 123456704, 123456705]
    try:
        for i, u in enumerate(_t_users):
            get_user(int(u))["xp"] = 100 * (5 - i)
        entry = v20_team_build(_t_probe, _t_users, None)
        n_red, n_blue = len(entry.get("red", [])), len(entry.get("blue", []))
        assert n_red + n_blue == 5 and abs(n_red - n_blue) <= 1, (n_red, n_blue)
        before = int(entry.get("points", {}).get("red", 0) or 0)
        member = int(entry["red"][0])
        _old_xp = int(get_user(member).get("xp", 0) or 0)
        try:
            add_xp(member, 5, "ProbeTeam")
        except Exception:
            pass
        entry2 = v20_team_entry(_t_probe)
        assert int(entry2.get("points", {}).get("red", 0) or 0) >= before + 5, "team credit failed"
        get_user(member)["xp"] = _old_xp
        txt_t = v20_team_text(_t_probe, None)
        assert "تیم‌های رقابتی" in txt_t and "امتیاز" in txt_t
    finally:
        try:
            v20_store()["teams"].pop(group_key(_t_probe), None)
            for k in _t_users:
                DATA.get("users", {}).pop(user_key(int(k)), None)
        except Exception:
            pass
    # ۱۲) چالش روزانه: شمارش + هدف + جایزه‌ی یک‌باره
    _d_probe = -100773
    try:
        # ریستِ پروب برای idempotency در ری‌استارت‌های هم‌روز
        v20_store()["daily"][group_key(_d_probe)] = {
            "date": v20_day_key(), "turns": 0, "claimed": False, "players": {},
        }
        e = v20_daily_entry(_d_probe)
        base_turns = int(e.get("turns", 0) or 0)
        fake_game = {"chat_id": _d_probe, "id": "v20probe"}
        v20_daily_tick(fake_game, 111222333)
        assert int(v20_daily_entry(_d_probe)["turns"]) == base_turns + 1, "daily tick failed"
        e = v20_daily_entry(_d_probe)
        e["turns"] = int(v20_gcfg(_d_probe)["daily_goal"]) - 1
        e["players"] = {user_key(111222333): 1}
        v20_store()["daily"][group_key(_d_probe)] = e
        _coins_before = int(get_user(111222333).get("coins", 0) or 0)
        v20_daily_tick(fake_game, 111222333)
        assert v20_daily_entry(_d_probe).get("claimed") is True, "daily not claimed"
        # پاداش از طریق تسکِ زمان‌بندی‌شده می‌آید؛ اینجا مستقیم اجرا می‌کنیم
        import asyncio as _v20_aio
        _v20_aio.run(v20_daily_celebrate(_d_probe, v20_daily_entry(_d_probe)))
        assert int(get_user(111222333).get("coins", 0) or 0) >= _coins_before + 8, "daily reward failed"
        txt_d = v20_daily_text(_d_probe)
        assert "چالش روزانه" in txt_d and "کامل شد" in txt_d
    finally:
        try:
            v20_store()["daily"].pop(group_key(_d_probe), None)
            DATA.get("users", {}).pop(user_key(111222333), None)
        except Exception:
            pass
    # ۱۳) قلب: شمارنده‌ی روزانه
    assert v20_hearts_today(987654321) == 0
    try:
        v20_store()["hearts"].pop(v20_day_key(), None)
    except Exception:
        pass
    # ۱۴) آمار گروه + جشن رکورد + متن گزارش
    _g_probe = -100774
    try:
        # ریستِ پروب برای idempotency کامل در ری‌استارت‌ها
        v20_store()["gstats"][group_key(_g_probe)] = {
            "week": v19_week_key(), "games": 0, "turns": 0, "milestone": 0, "ts": v20_now(),
        }
        for _ in range(10):
            v20_game_ended({"chat_id": _g_probe, "id": "v20probe2"})
        e = v20_gstats_entry(_g_probe)
        assert int(e.get("games", 0) or 0) == 10 and int(e.get("milestone", 0) or 0) == 10, (e.get("games"), e.get("milestone"))
        txt_r = v20_recap_text(_g_probe)
        assert "گزارش هفتگی گروه" in txt_r
    finally:
        try:
            v20_store()["gstats"].pop(group_key(_g_probe), None)
        except Exception:
            pass
    # ۱۵) مرکز راهنما گسترش یافته
    assert len(V18_HELP_CENTER_EXTRA) >= 10
    # ۱۶) قلاب کلاس Bot نصب شده (در محیطی که telegram موجود است)
    if _V20_PATCH_OK:
        import telegram as _v20_t2
        assert getattr(_v20_t2.Bot.send_message, "__name__", "") == "v20_bot_send_message"
        assert getattr(_v20_t2.Bot.edit_message_text, "__name__", "") == "v20_bot_edit_text"
    # ۱۷) شبیه‌سازی کامل چرخه‌ی پنل (اگر داخل لوپ نباشیم)
    sim_ok = None
    try:
        asyncio.get_running_loop()
    except RuntimeError:
        sim_ok = asyncio.run(v20_self_check_async())
    assert sim_ok is not False, "v20 panel lifecycle simulation failed"
    # ۱۹) جاروی نهایی: همه‌ی پروب‌ها از فایل پاک و ذخیره شوند (ضد آجرِ ری‌استارت)
    v20_sanitize_probes()
    # ۱۸) قلاب‌های ادیت/ارسال داخل شبکه‌ی واقعی لازم‌اند
    assert callable(_V20_ORIG_SEND) and callable(_V20_ORIG_EDIT)
    print(
        f"ApexRival V20 self-check OK | new-prompts={total_new} | panel-manager=on | "
        "back-nav=on | close-deletes=on | teams=on | daily=on | hearts=on | "
        f"brb=on | recap=on | milestones=on | panel-sim={'OK' if sim_ok else 'SKIPPED'}"
    )


v20_self_check()



